const ozStatistics3Orta = <(String, String, List<String>, String)>[
  ('Posta kodları sayılardan oluştuğu hâlde istatistikte genellikle nitel veri sayılır. Bunun temel nedeni nedir?', 'Sayılar bir büyüklüğü değil, bir bölgenin etiketini gösterir.', ['Posta kodları her zaman beş basamaklıdır.', 'Posta kodları sıfırla başlayabilir.', 'Posta kodları devlet tarafından belirlenir.'], 'Posta kodlarını toplamak ya da ortalamasını almak anlamlı değildir; sayılar yalnızca etiket işlevi görür.'),
  ('Bir kafede müşterilere \'Kahvenizi nasıl buldunuz: kötü, orta, iyi?\' diye soruluyor. Toplanan yanıtlar için hangisi doğrudur?', 'Sıralanabilen nitel veridir.', ['Sürekli nicel veridir.', 'Sırası olmayan sayısal veridir.', 'Oran ölçekli nicel veridir.'], 'Kötü-orta-iyi kategorileri arasında doğal bir sıra vardır ama değerler sayısal ölçüm değildir; sıralı nitel veridir.'),
  ('Bir okul, öğrencilerin servis kullanıp kullanmadığını \'evet=1, hayır=0\' biçiminde kodluyor. Bu kodlanmış değişken için hangisi doğrudur?', 'Kodlar sayı olsa da değişken nitel kalır.', ['Kodlama değişkeni sürekli nicel veriye çevirir.', 'Kodlama sonrası değişken oran ölçekli olur.', 'Kodlama veriyi ikincil veriye dönüştürür.'], 'Sayısal kodlama yalnızca kategorileri temsil eder; değişkenin doğası değişmez, yine nitel (iki kategorili) veridir.'),
  ('Santigrat cinsinden ölçülen hava sıcaklığı hangi ölçek düzeyindedir?', 'Aralık ölçeği', ['Oran ölçeği', 'Sıralama ölçeği', 'Sınıflama ölçeği'], '0 °C sıcaklığın yokluğu anlamına gelmez; sıfır keyfî olduğu için santigrat sıcaklık aralık ölçeğidir.'),
  ('Oran ölçeğini aralık ölçeğinden ayıran özellik hangisidir?', 'Gerçek (mutlak) bir sıfır noktasının bulunması', ['Değerlerin sıralanabilmesi', 'Değerler arasındaki farkların eşit ve anlamlı olması', 'Değerlerin kategorilere ayrılabilmesi'], 'Oran ölçeğinde sıfır, ölçülen niceliğin yokluğu anlamına gelir; bu sayede \'iki katı\' gibi oran karşılaştırmaları anlamlıdır.'),
  ('Bir anket maddesinde askerlik rütbeleri (er, onbaşı, çavuş, teğmen) kaydediliyor. Bu değişkenin ölçek düzeyi nedir?', 'Sıralama ölçeği', ['Sınıflama ölçeği', 'Aralık ölçeği', 'Oran ölçeği'], 'Rütbeler arasında belirgin bir hiyerarşi vardır ama aralarındaki \'mesafe\' sayısal olarak eşit değildir.'),
  ('Bir araştırmacı öğrencilerin aylık harçlığını Türk lirası cinsinden kaydediyor. Harçlığı hiç olmayan öğrenciler 0 TL olarak yazılıyor. Bu değişken hangi ölçek düzeyindedir?', 'Oran ölçeği', ['Aralık ölçeği', 'Sıralama ölçeği', 'Sınıflama ölçeği'], '0 TL paranın gerçekten yokluğunu gösterir; bu nedenle 200 TL\'nin 100 TL\'nin iki katı olduğu söylenebilir ve değişken oran ölçeğindedir.'),
  ('Ölçek düzeyleri en az bilgi taşıyandan en çok bilgi taşıyana doğru nasıl sıralanır?', 'Sınıflama, sıralama, aralık, oran', ['Sıralama, sınıflama, oran, aralık ölçeği', 'Aralık, oran, sınıflama, sıralama', 'Sınıflama, aralık, sıralama, oran'], 'Her üst düzey bir alttakinin tüm özelliklerini taşır ve yeni bir özellik ekler: sıra, eşit aralık, gerçek sıfır.'),
  ('Kelvin cinsinden sıcaklık hangi ölçek düzeyindedir?', 'Oran ölçeği', ['Aralık ölçeği', 'Sıralama ölçeği', 'Sınıflama ölçeği'], '0 K mutlak sıfırdır, yani ısıl hareketin yokluğunu gösterir; bu nedenle Kelvin oran ölçeğidir.'),
  ('İkincil veri kullanmanın en önemli avantajı aşağıdakilerden hangisidir?', 'Zaman ve maliyetten tasarruf sağlaması', ['Araştırma sorusuna tam olarak uyması', 'Verinin nasıl toplandığının araştırmacı tarafından denetlenmesi', 'Her zaman en güncel bilgiyi içermesi'], 'İkincil veri hazır olduğundan hızlı ve ucuzdur; ancak araştırma sorusuna tam uymayabilir ve toplama süreci denetlenemez.'),
  ('Bir öğrenci ödevinde, bir dergide yayımlanmış başka bir araştırmanın anket sonuçlarını kullanıyor; ardından aynı soruları kendi sınıfına da soruyor. Bu durumda öğrenci hangi veri türlerini kullanmıştır?', 'Hem ikincil hem birincil veri', ['Yalnızca birincil veri', 'Yalnızca ikincil veri', 'Yalnızca tam sayım verisi'], 'Dergideki sonuçlar ikincil veridir; kendi sınıfından topladığı yanıtlar ise birincil veridir.'),
  ('Bir anket şirketi \'Türkiye\'deki seçmenlerin görüşleri\' hakkında sonuç açıklıyor, ancak yalnızca üç büyükşehirde anket yapmış. Bu çalışmadaki temel sorun nedir?', 'Örneklem, sonuçların genellendiği anakütleyi temsil etmiyor.', ['Örneklem büyüklüğü her durumda çok büyük olmuştur.', 'Büyükşehirlerde anket yapmak yasal değildir.', 'Seçmen görüşleri nicel veri olmadığı için ölçülemez.'], 'Kırsal kesim ve diğer iller örneklemde yer almadığından sonuçlar tüm seçmenlere genellenemez.'),
  ('Aşağıdaki durumların hangisinde araştırılan grup doğrudan bir anakütle olarak düşünülmelidir ve örneklem seçmeye gerek yoktur?', 'Bir öğretmenin yalnızca kendi 28 kişilik sınıfının not ortalamasını merak etmesi', ['Bir ülkedeki hanelerin ortalama gelirinin tahmin edilmesi', 'Bir okyanustaki balık nüfusunun tahmin edilmesi', 'Bir ilaç fabrikasındaki tabletlerin dayanıklılığının kırma testiyle denetlenmesi'], 'Grup küçük ve tamamen erişilebilir olduğundan öğretmen 28 öğrencinin tamamının verisini kolayca toplayabilir.'),
  ('2020\'de bir okulun kayıt sisteminden okulun tüm öğrencilerinin yaş ortalaması 15,4 olarak hesaplanıyor. Bu değer için hangisi doğrudur?', 'Tüm öğrenciler kullanıldığı için bir parametredir.', ['Kayıt sisteminden alındığı için bir istatistiktir.', 'Bir ortalama olduğu için örneklem büyüklüğü olarak yorumlanır.', 'Yaş nitel bir değişken olduğundan anlamsızdır.'], 'Okulun bütün öğrencileri anakütle olarak ele alınıp hesaplama hepsini kapsadığından elde edilen değer parametredir.'),
  ('İstatistiklerin parametrelerden önemli bir farkı nedir?', 'Seçilen örnekleme göre değer değiştirebilmeleri', ['Her zaman parametreden büyük olmaları', 'Yalnızca nitel değişkenler için hesaplanmaları', 'Hiçbir zaman ondalıklı olmamaları'], 'Farklı örneklemler farklı istatistik değerleri verir; parametre ise belirli bir anakütle için sabittir.'),
  ('Bir seçim anketinde 1200 kişiden %46\'sının A adayını desteklediği bulunuyor. Seçim günü tüm seçmenlerin %44\'ünün A adayına oy verdiği ortaya çıkıyor. Bu iki sayı için doğru eşleştirme hangisidir?', '%46 istatistik, %44 parametre', ['%46 parametre, %44 istatistik', 'İkisi de anakütleye ait parametre değeri', 'İkisi de istatistik'], '%46 örneklemden, %44 ise tüm seçmenlerden elde edildiği için sırasıyla istatistik ve parametredir.'),
  ('Aynı anakütleden iki farklı araştırmacı birbirinden bağımsız 100\'er kişilik rastgele örneklem seçiyor ve ortalama boyu biri 168,2 cm, diğeri 169,1 cm buluyor. Bu farkın en olası açıklaması nedir?', 'Örnekleme değişkenliği', ['Anakütle parametresinin değişmesi', 'Ölçek düzeyinin farklı olması', 'Verilerin nitel olması'], 'Rastgele örneklemler şansa bağlı olarak farklı birimler içerir; bu yüzden istatistikler örneklemden örnekleme değişir.'),
  ('Örneklemenin tam sayıma göre üstünlüklerinden biri hangisi değildir?', 'Örnekleme hatasını tamamen ortadan kaldırması', ['Daha düşük maliyetli olması', 'Daha kısa sürede sonuç vermesi', 'Daha az sayıda birimle daha dikkatli ölçüm yapılabilmesi'], 'Örnekleme, tanımı gereği örnekleme hatası içerir; bu hatayı ortadan kaldıran tam sayımdır.'),
  ('Basit rastgele örnekleme uygulayabilmek için öncelikle neye ihtiyaç vardır?', 'Anakütledeki bütün birimleri içeren bir listeye', ['Anakütlenin tabakalara ayrılmasına', 'Gönüllü katılımcılara', 'Araştırmacının uzman görüşüne'], 'Her birime eşit şans tanıyabilmek için birimlerin eksiksiz bir listesi (örnekleme çerçevesi) gerekir.'),
  ('Bir öğrenci okulun 800 öğrencisinden rastgele örneklem seçmek için her öğrenciye 001\'den 800\'e kadar numara veriyor. Rastgele sayı üreticisi sırasıyla 512, 847, 093, 512, 270 sayılarını veriyor. 3 öğrenci seçilecekse hangi numaralar seçilir?', '512, 093, 270', ['512, 847, 093', '512, 093, 512', '847, 093, 270'], '800\'den büyük olan 847 atlanır; tekrar eden 512 ikinci kez alınmaz. Böylece 512, 093 ve 270 seçilir.'),
  ('Bir araştırmacı, alışveriş merkezinin girişinde \'rastgele\' gördüğü kişileri durdurup anket uyguladığını söylüyor. Bu yöntem neden basit rastgele örnekleme sayılmaz?', 'Anakütledeki herkesin seçilme şansı eşit değildir ve seçim araştırmacının tercihine bağlıdır.', ['Alışveriş merkezlerinde anket yapılamaz.', 'Seçilen kişi sayısı önceden belirlenmemiştir.', 'Anket soruları kapalı uçludur.'], 'Gelişigüzel seçim rastgele seçim değildir; o gün o merkeze gitmeyenler hiç seçilemez ve araştırmacı yaklaşmak istediği kişileri seçebilir.'),
  ('Basit rastgele örneklemede \'iadesiz seçim\' ne anlama gelir?', 'Seçilen birim bir daha seçilemez.', ['Seçilen birim listeye geri konur ve yeniden seçilebilir.', 'Seçim yalnızca listenin başındaki birimlerden yapılır.', 'Seçilen her birim örneklemden sonradan çıkarılır.'], 'İadesiz seçimde bir birim örnekleme bir kez girer; bu nedenle aynı birim iki kez yer almaz.'),
  ('50 kişilik bir kulüpten basit rastgele örnekleme ile 10 kişi seçilecek. Kulüpteki belirli bir üyenin örnekleme girme olasılığı kaçtır?', '0,2', ['0,1', '0,02', '0,5'], 'Basit rastgele örneklemede her birimin seçilme olasılığı n/N = 10/50 = 0,2\'dir.'),
  ('Bir okul 600 öğrencilik alfabetik listeden k=15 ile sistematik örneklem seçiyor ve rastgele başlangıç numarası 7 çıkıyor. Örnekleme giren dördüncü öğrencinin sıra numarası kaçtır?', '52', ['60', '105', '67'], 'Seçilen numaralar 7, 22, 37, 52 ... biçiminde ilerler; dördüncü numara 7 + 3·15 = 52\'dir.'),
  ('Sistematik örneklemenin basit rastgele örneklemeye göre pratik avantajı nedir?', 'Uygulaması daha kolay ve hızlıdır.', ['Her zaman daha küçük örnekleme hatası verir.', 'Liste olmadan da uygulanabilmesi en büyük avantajıdır.', 'Anakütledeki periyodik düzenlerden hiç etkilenmez.'], 'Tek bir rastgele başlangıçtan sonra sabit aralıkla seçim yapmak, çok sayıda rastgele sayı üretmekten daha pratiktir.'),
  ('Bir şirkette 300 mühendis, 150 teknisyen ve 50 yönetici çalışıyor. Orantılı tabakalı örnekleme ile 60 kişilik örneklem seçilirse kaç teknisyen seçilir?', '18', ['20', '150', '30'], 'Teknisyenlerin oranı 150/500 = 0,3\'tür; 60 · 0,3 = 18 teknisyen seçilir.'),
  ('Tabakalı örnekleme ile kota örneklemesi arasındaki temel fark nedir?', 'Tabakalıda tabaka içi seçim rastgeledir, kotada değildir.', ['Kota örneklemesinde gruplar hiç kullanılmaz ve seçim tamamen rastgele yapılır.', 'Tabakalı örneklemede örneklem büyüklüğü önceden hiç belirlenmez.', 'Kota örneklemesi yalnızca nüfus sayımlarında kullanılan bir yöntemdir.'], 'Her iki yöntem de grupları kullanır; ancak kotada grup içindeki kişileri araştırmacı istediği gibi seçer, tabakalıda seçim rastgeledir.'),
  ('Bir anket şirketi bölgelere göre tabakalı örnekleme yapıyor. Bu tasarımın hangi sonucu doğurması beklenir?', 'Her bölgenin örneklemde mutlaka temsil edilmesi', ['Yalnızca en kalabalık bölgenin örneklemde yer alması', 'Örnekleme hatasının sıfıra inmesi', 'Bölgelerden yalnızca birinin rastgele seçilmesi'], 'Tabakalama, her tabakadan seçim yapıldığı için hiçbir alt grubun şans eseri dışarıda kalmamasını sağlar.'),
  ('Küme örneklemesi en çok hangi durumda tercih edilir?', 'Anakütle geniş bir alana yayıldığında ve tam bireysel liste bulunmadığında', ['Anakütle küçük olduğunda ve herkesin adı tek tek bilindiğinde', 'Tabakalar birbirinden çok farklı olduğunda ve her biri temsil edilmelidir', 'Araştırmacı yalnız uzman görüşüne başvurmak istediğinde'], 'Kümeler seçilerek yolculuk ve liste hazırlama maliyeti azaltılır; yalnızca seçilen kümelerin bireysel listesi gerekir.'),
  ('Tabakalı örnekleme ile küme örneklemesi arasındaki fark için hangisi doğrudur?', 'Tabakalıda her gruptan seçim yapılır; kümede grupların yalnızca bir kısmı seçilir.', ['Tabakalıda grupların bir kısmı seçilir; küme örneklemesinde her gruptan mutlaka birey alınır.', 'İki yöntem de aynıdır; yalnızca kullanılan isimler farklıdır.', 'Küme örneklemesinde gruplar her zaman tek bir kişiden oluşur.'], 'Tabakalamada bütün tabakalar örnekleme katılır; kümelemede rastgele seçilen bazı kümeler incelenir.'),
  ('Ülke çapındaki hane anketlerinde çok aşamalı örneklemenin yaygın kullanılmasının nedeni nedir?', 'Tüm hanelerin tek bir listesine gerek kalmaması', ['Örnekleme hatasını tamamen ortadan kaldırması', 'Yalnızca bir ilde çalışmayı mümkün kılması', 'Gönüllü katılımcıları öne çıkarması'], 'Her aşamada yalnızca seçilen birimlerin alt listesi gerekir; bu da ulusal ölçekte maliyeti büyük ölçüde azaltır.'),
  ('Bir televizyon programı, stüdyodaki seyircilere el kaldırtarak \'Türk halkının çoğu bu yasayı destekliyor.\' sonucuna varıyor. Bu çıkarım için en yerinde eleştiri hangisidir?', 'Stüdyo seyircisi kolayda seçilmiş bir gruptur; sonuç halka genellenemez.', ['El kaldırma yöntemi yalnızca kesikli veriler için geçerli bir yöntemdir.', 'Stüdyodaki seyirci sayısı anakütleden daha büyük olduğu için hata vardır.', 'Bu yöntem tabakalı örnekleme olduğundan sonuç kesin olarak doğrudur.'], 'Programa gelenler belirli ilgi ve özelliklere sahip olabilir; rastgele seçilmedikleri için halkı temsil etmezler.'),
  ('Kolayda örnekleme hangi amaçla kullanıldığında en az sakıncalıdır?', 'Anket sorularını ön denemeden geçirmek', ['Ülke çapında seçim sonucunu tahmin etmek', 'Bir ilacın tüm nüfustaki yan etki oranını kesin olarak belirlemek', 'Resmî işsizlik oranını hesaplayıp açıklamak'], 'Ön deneme amacı soruların anlaşılırlığını sınamaktır; genelleme yapılmadığı için kolayda seçilen kişiler yeterli olabilir.'),
  ('Bir psikoloji öğretmeni deneyine yalnızca kendi derslerindeki öğrencileri katıyor. Bu durumun sonuçlar üzerindeki olası etkisi nedir?', 'Bulgular yalnız benzer öğrencilere genellenebilir.', ['Bulgular otomatik olarak tüm insanlara genellenebilir hâle gelir.', 'Örnekleme hatası tamamen ortadan kalkar ve sonuç kesinleşir.', 'Veriler nitel olmaktan çıkar ve nicel veriye dönüşür.'], 'Kolayda seçilmiş bir grup belli yaş, eğitim ve ilgi alanına sahiptir; sonuçların geniş kitlelere aktarımı sınırlıdır.'),
  ('Aşağıdakilerden hangisi kolayda örneklemeye örnek değildir?', 'Okul listesinden rastgele sayılarla 40 öğrenci seçmek', ['Sokakta ilk karşılaşılan 40 kişiyle görüşmek', 'Araştırmacının kendi akrabalarına anket uygulaması', 'Parkta bankta oturanlara soru sormak'], 'Listeden rastgele seçim, her öğrenciye eşit şans tanıdığı için olasılıklı örneklemedir.'),
  ('Kota örneklemesinde kotaların nüfus oranlarına uygun belirlenmesine rağmen sonuçların yanlı çıkabilmesinin nedeni nedir?', 'Görüşmecinin kişi seçiminin yanlı olabilmesi', ['Kotaların her zaman yanlış hesaplanması zorunluluğu', 'Kota örneklemesinin yalnızca tek kişiyle yapılabilmesi', 'Kotaların doldurulmasının yasal olarak yasak olması'], 'Görüşmeciler kotaları doldururken kolay ulaşılan ya da işbirliğine yatkın kişileri seçebilir; bu, kotalarla düzeltilmeyen bir yanlılık yaratır.'),
  ('Kartopu örneklemesi en çok hangi tür anakütleler için uygundur?', 'Ulaşılması zor ya da listesi olmayan gruplar', ['Liste hâlinde kayıtlı olan bütün okul öğrencileri', 'Seçmen kütüğüne kayıtlı tüm seçmenler', 'Bir fabrikanın bütün üretim partileri'], 'Nadir bir hastalığı olanlar ya da belirli bir zanaatın ustaları gibi gruplara birbirleri aracılığıyla ulaşmak daha kolaydır.'),
  ('Bir araştırmacı bir ilçedeki geleneksel bakır işleme ustalarını araştırıyor. İlk görüştüğü iki usta ona başka ustaları tanıtıyor, onlar da başkalarını. Bu yöntemin olası sakıncası nedir?', 'Birbirini tanıyan ustalar öne çıkabilir.', ['Ustalar rastgele seçildiği için yanlılık tamamen ortadan kalkar.', 'Her ustanın seçilme olasılığı eşit olduğundan ağırlık gerekir.', 'Bakır işleme verisi nicel olduğu için yöntem uygulanamaz.'], 'Zincir, ilk katılımcıların sosyal çevresiyle sınırlı kalabilir; kimseyle bağı olmayan ustalar örneklem dışında kalır.'),
  ('Nitel araştırmalarda amaçlı örneklemenin sık kullanılmasının nedeni nedir?', 'Derin bilgi sunabilecek kişilere ulaşmak', ['Sonuçları sayısal olarak tüm nüfusa genellemek', 'Örnekleme hatasını olasılık yoluyla hesaplamak', 'Anket maliyetini sıfıra indirmek'], 'Nitel araştırmalarda amaç genelleme değil derinlemesine anlamadır; bu yüzden konuyu iyi bilen kişiler bilerek seçilir.'),
  ('Gönüllü yanıt örneklemlerinde sonuçların genellikle hangi yönde çarpık olması beklenir?', 'Güçlü görüşü olanların ağırlığına doğru', ['Konuya tamamen ilgisiz olanların ağırlığına doğru', 'Anakütle ortalamasına tam olarak eşit olacak biçimde', 'Her zaman olumlu görüşlerin azalması yönünde'], 'Konuyla ilgili güçlü, çoğunlukla olumsuz duyguları olan kişiler katılmaya daha isteklidir; bu, sonuçları onların görüşüne kaydırır.'),
  ('Bir radyo programı dinleyicilerinden SMS ile \'Belediyenin yeni otopark ücreti adil mi?\' sorusuna yanıt istiyor; 2000 mesajın %85\'i \'hayır\' diyor. Bu sonuçla ilgili en doğru yorum hangisidir?', 'Katılımcılar kendini seçtiği için sonuç genellenemez.', ['2000 kişi geniş bir örneklem olduğu için sonuç kesinlikle doğrudur.', 'SMS yöntemi tabakalı örnekleme olduğundan yanlılık yoktur.', '%85 değeri şehrin tüm nüfusu için hesaplanmış bir parametredir.'], 'Büyük örneklem, gönüllü katılımdan kaynaklanan yanlılığı düzeltmez; ücretten rahatsız olanlar katılmaya daha istekli olabilir.'),
  ('Bir araştırmacı gönüllü yanıt örneklemesindeki yanlılığı azaltmak istiyor. Aşağıdakilerden hangisi en etkili adımdır?', 'Katılımcıları rastgele seçip kendisi ulaşmak', ['Anketi daha fazla sosyal medya hesabında paylaşmak', 'Yanıt süresini bir haftadan bir aya çıkarmak', 'Anketi yalnızca konuya en ilgili kişilere duyurmak'], 'Yanlılığın kaynağı katılımcıların kendini seçmesidir; rastgele seçim yapıp kişilere ulaşmak bu kaynağı ortadan kaldırır.'),
  ('Bir araştırmacı bir kentteki yetişkinlere ulaşmak için sabit telefon rehberini örnekleme çerçevesi olarak kullanıyor. Bu tercihin temel sorunu nedir?', 'Sabit hattı olmayanlar seçilemez.', ['Telefon rehberi çok kısa olduğu için rastgele seçim yapılamaz.', 'Rehberdeki her kişi iki kez seçilmek zorundadır.', 'Sabit telefon kullanan herkes aynı görüşe sahiptir.'], 'Çerçeve anakütlenin bir kısmını dışarıda bıraktığında kapsam hatası oluşur; sabit hat sahipleri tüm yetişkinleri temsil etmeyebilir.'),
  ('İdeal bir örnekleme çerçevesi için hangisi doğrudur?', 'Anakütledeki her birimi bir kez içerir.', ['Anakütledeki birimlerin yalnızca yarısını içermesi yeterlidir.', 'Bazı birimleri bilerek birden fazla kez içermesi gerekir.', 'Anakütle dışından birimleri de mutlaka kapsaması beklenir.'], 'Çerçeve eksik birim, fazla birim ya da yinelenen kayıt içermemelidir; aksi hâlde seçilme olasılıkları bozulur.'),
  ('1936 ABD başkanlık seçiminde Literary Digest dergisinin Landon\'ın kazanacağını öngörmesinin başlıca nedenlerinden biri nedir?', 'Örnekleme listelerinin varlıklı kesimleri öne çıkarması', ['Ankete yalnızca 50 kişinin katılmış olması', 'Anket sorularının açık uçlu sorulmuş olması', 'Sonuçların yanlış toplanmış olması'], 'Dergi listelerini telefon rehberleri, araç kayıtları ve abone listelerinden almıştı; Büyük Buhran yıllarında bu listeler varlıklıları fazla temsil ediyordu.'),
  ('Seçim yanlılığı (seçilim yanlılığı) en iyi hangi ifadeyle tanımlanır?', 'Örneklemin anakütleden sistematik olarak farklı olması', ['Örneklemden örnekleme şans eseri oluşan küçük farklar', 'Verilerin bilgisayara yanlış girilmesi', 'Örneklem büyüklüğünün hesaplanmasındaki aritmetik hata'], 'Seçim yanlılığı rastgele değil, seçim yönteminden kaynaklanan tutarlı bir farklılaşmadır.'),
  ('Bir spor salonu üyelerinin ortalama haftalık egzersiz süresini yalnızca salonda sabah 7\'de bulunan üyelere sorarak tahmin ediyor. Bu tahmin büyük olasılıkla nasıl olur?', 'Olduğundan yüksek', ['Olduğundan düşük', 'Tam olarak doğru', 'Yönü kestirilemeyecek kadar rastgele'], 'Sabah erkenden salonda olanlar büyük olasılıkla daha düzenli spor yapan üyelerdir; bu da tahmini yukarı çeker.'),
  ('Bir hastane, tedavi memnuniyetini yalnızca taburcu olan hastalara soruyor; yoğun bakımda kalanlar ve vefat edenler dışarıda kalıyor. Bu durum hangi hataya örnektir?', 'Kapsam hatası', ['Ölçek düzeyi hatası', 'Veri giriş hatası', 'Yuvarlama hatası'], 'Anakütlenin önemli bir kısmı örnekleme sürecinde seçilme şansı bulamadığı için kapsam hatası oluşur.'),
  ('Bir dergi, \'Başarılı girişimcilerin %80\'i üniversiteyi bırakmıştır.\' diyerek okulu bırakmanın başarı getirdiğini öne sürüyor. Bu çıkarımdaki temel yanlılık hangisidir?', 'Başarısız olanların incelenmemesi', ['Başarılı girişimcilerin sayısının çok fazla olması', 'Üniversite verilerinin nitel olması', 'Derginin ikincil veri kullanması'], 'Okulu bırakıp başarısız olan çok sayıda kişi incelenmediği için \'hayatta kalan\' örneklemden yanlış bir genelleme yapılmıştır.'),
  ('Uzun çalışma saatleri hakkında yapılan bir telefon anketinde aramalar yalnızca hafta içi gündüz saatlerinde yapılıyor. Bu durumun en olası sonucu nedir?', 'Çok çalışanlar yanıtsız kalır.', ['Çok çalışanların görüşleri olduğundan daha fazla temsil edilir.', 'Anket sonuçları kesinlikle değişmeden doğru kalır.', 'Yalnızca nitel veri elde edilebileceği için anket iptal olur.'], 'Gündüz evde olmayan, uzun saat çalışan kişilere ulaşılamaz; araştırılan konuyla doğrudan ilişkili bir grup yanıtsız kalır.'),
  ('Yanıtsızlık yanlılığı ile kapsam hatası arasındaki fark nedir?', 'Kapsamda kişi seçilemez; yanıtsızlıkta seçilip yanıt vermez.', ['Kapsam hatası yalnızca telefon anketlerinde ortaya çıkan bir hatadır.', 'Yanıtsızlık yalnızca tam sayımlarda ortaya çıkan bir hatadır.', 'İki kavram arasında hiçbir fark yoktur.'], 'Kapsam hatası çerçevenin eksikliğinden, yanıtsızlık ise seçilen birimlerin katılmamasından kaynaklanır.'),
  ('Seçim sonrası yapılan anketlerde \'oy verdim\' diyenlerin oranının resmî katılım oranından yüksek çıkması sıkça görülür. Bunun en olası açıklaması nedir?', 'Oy vermeyenlerin oy verdim demesi', ['Resmî katılım sayımının her zaman hatalı olması', 'Anketlerin yalnızca oy verenlere yapılması zorunluluğu', 'Oy verme davranışının nitel olmaması'], 'Oy kullanmak toplumsal olarak beğenilen bir davranıştır; bazı katılımcılar oy vermemiş olsalar da öyle demeyi tercih eder.'),
  ('Bir görüşmecinin ses tonu, giyimi ya da tepkileri nedeniyle katılımcıların yanıtlarının değişmesine ne ad verilir?', 'Görüşmeci etkisi', ['Yanıtsızlık yanlılığı', 'Örnekleme çerçevesi hatası', 'Kota hatası'], 'Görüşmecinin kendisi yanıtları etkileyen bir faktöre dönüştüğünde görüşmeci etkisi (yanlılığı) ortaya çıkar.'),
  ('Bir araştırmacı katılımcılardan geçen yıl kaç kez dışarıda yemek yediklerini hatırlamalarını istiyor. Bu tür sorularda karşılaşılan önemli sorun hangisidir?', 'Hatırlama yanlılığı', ['Kapsam hatası', 'Kota yanlılığı', 'Tabakalama sırasında yapılan hata'], 'Uzun dönemi kapsayan sorularda insanlar olayları yanlış anımsayabilir; yakın olayları abartıp uzak olanları unutabilir.'),
  ('\'Çocukların sağlığını tehdit eden gazlı içeceklerin okul kantinlerinde satışı yasaklanmalı mı?\' sorusundaki sorun nedir?', 'Sorudaki yargı yanıtı yönlendiriyor.', ['Soru açık uçlu olduğu için yanıtlar kodlanamaz.', 'Soru birden çok seçenek sunduğu için karmaşıktır.', 'Soru ölçek düzeyini belirtmediği için geçersizdir.'], '\'Sağlığı tehdit eden\' ifadesi katılımcıyı \'evet\' demeye yönlendirir; tarafsız bir soru bu yargıyı içermez.'),
  ('Bir anket sorusu \'Uzmanların çoğu düzenli kitap okumanın yararlı olduğunu söylüyor. Siz haftada kaç saat kitap okursunuz?\' biçiminde yazılmış. Bu sorunun ürettiği verinin hangi yönde yanlı olması beklenir?', 'Okuma süresi olduğundan fazla bildirilir.', ['Okuma süresi olduğundan az bildirilir.', 'Yanıtlarda giriş cümlesinden kaynaklı değişiklik beklenmez.', 'Yanıtlar yalnızca nitel veriye dönüşür.'], 'Giriş cümlesi okumayı olumlu bir davranış olarak sunar; bu, katılımcıları okuma süresini abartmaya yöneltir.'),
  ('Aşağıdaki ifadelerden hangisi bir anket sorusunda \'varsayım içeren soru\' hatasına örnektir?', 'Spor yapmayı ne zaman bıraktınız?', ['Haftada kaç gün spor yaparsınız?', 'Spor yapıyor musunuz?', 'En sevdiğiniz spor dalı hangisidir?'], 'Soru, kişinin daha önce spor yaptığını ve bıraktığını varsayar; bu varsayım herkes için geçerli olmayabilir.'),
  ('\'Sık sık spor yapar mısınız?\' sorusunun ölçme açısından zayıf yanı nedir?', '\'Sık sık\' herkes için farklı anlama gelir.', ['Soru iki ayrı konuyu aynı anda soruyor.', 'Soru katılımcıyı olumsuz yanıta yönlendiriyor.', 'Soru açık uçlu olduğu için analiz edilemez.'], 'Belirsiz sıklık ifadeleri farklı yorumlanır; \'Son bir haftada kaç gün en az 30 dakika spor yaptınız?\' gibi somut bir ifade daha iyidir.'),
  ('Hangi soru, belirsizlik bakımından en iyi yazılmış sorudur?', 'Son 7 günde kaç saat televizyon izlediniz?', ['Çok televizyon izler misiniz?', 'Genelde televizyon izliyor musunuz?', 'Televizyonu normal düzeyde mi izlersiniz?'], 'Zaman dilimi ve ölçü birimi belli olan soru herkes tarafından aynı biçimde anlaşılır.'),
  ('Bir ankette \'Okulda cep telefonu yasağının kaldırılmaması gerektiğine katılmıyor musunuz?\' sorusu yer alıyor. Bu sorunun asıl sorunu nedir?', 'Çoklu olumsuzluk soruyu anlaşılmaz yapıyor.', ['Soru çok kısa olduğu için anlamsızdır.', 'Soru yalnızca bir konuyu ölçtüğü için yetersizdir.', 'Soru sayısal bir yanıt gerektirdiği için hatalıdır.'], 'Birden fazla olumsuz ifade (\'kaldırılmaması\', \'katılmıyor musunuz\') katılımcıların soruyu yanlış anlamasına yol açar.'),
  ('Gençlere yönelik bir ankette \'Ergonomik olmayan mobilyaların muskuloskeletal etkileri sizi kaygılandırıyor mu?\' sorusu soruluyor. Bu sorunun en belirgin sorunu nedir?', 'Hedef kitleye uygun olmayan teknik dil', ['Sorunun iki ayrı konuyu birden sorması', 'Sorunun açık uçlu olması', 'Sorunun aşırı kısa olması'], 'Katılımcının anlamadığı terimler yanıtları rastgele ya da yanlış yönlü kılar; sorular hedef kitlenin diliyle yazılmalıdır.'),
  ('\'Ailenizin geliri nedir?\' sorusunu daha iyi hâle getirmek için yapılabilecek en uygun düzenleme hangisidir?', 'Gelir aralıkları ve dönemi belirten seçenekler sunmak', ['Soruyu \'Zengin misiniz?\' biçiminde sormak', 'Soruyu anketin ilk sorusu yapmak', 'Yanıtı zorunlu tutup boş bırakmayı yasaklamak'], 'Aylık ya da yıllık olduğu belirtilmiş gelir aralıkları belirsizliği azaltır ve hassas bir soruyu yanıtlamayı kolaylaştırır.'),
  ('Bir araştırmacı yeni bir konuda ön araştırma yapıyor ve olası yanıtların neler olabileceğini bilmiyor. Bu aşamada hangi soru türünü tercih etmesi daha uygundur?', 'Açık uçlu sorular', ['Yalnızca evet-hayır soruları', 'Yalnızca beşli derecelendirme soruları', 'Sıralama soruları'], 'Olası yanıtlar bilinmediğinde açık uçlu sorular, ileride kapalı uçlu seçeneklerin hazırlanmasına da yardımcı olur.'),
  ('\'Kaç yaşındasınız? a) 10–20 b) 20–30 c) 30–40 d) 40 ve üstü\' sorusundaki hata nedir?', 'Seçenekler birbirini dışlamıyor.', ['Dört seçenek bir yaş sorusu için fazla sayıdadır.', 'Soru açık uçlu olduğu için kodlanamaz.', 'Yaş nitel bir değişken olduğundan aralık verilemez.'], '20, 30 ve 40 yaşındakiler iki seçeneğe birden girer; aralıklar örneğin 10–19, 20–29 biçiminde düzenlenmelidir.'),
  ('Açık uçlu soruların çözümlenmesinde yaygın olarak yapılan ilk iş nedir?', 'Yanıtları kategorilere ayırıp kodlamak', ['Yanıtların aritmetik ortalamasını almak', 'Yanıtları rastgele silip örneklemi küçültmek', 'Yanıtları sayısal ölçeğe doğrudan çevirmek'], 'Serbest metin yanıtları benzer temalara göre kodlanarak sayılabilir kategorilere dönüştürülür.'),
  ('Tek bir Likert maddesine verilen yanıtlar ölçek düzeyi bakımından en doğru nasıl sınıflandırılır?', 'Sıralama ölçeği', ['Oran ölçeği', 'Sınıflama ölçeği', 'Mutlak sıfırlı ölçek'], 'Kategoriler sıralanabilir, ancak \'katılıyorum\' ile \'kesinlikle katılıyorum\' arasındaki uzaklığın diğerleriyle eşit olduğu garanti değildir.'),
  ('Likert ölçeğinde ortada \'Kararsızım\' seçeneğine yer verilmemesinin (çift sayılı ölçek kullanılmasının) amacı genellikle nedir?', 'Katılımcıyı bir yöne karar vermeye zorlamak', ['Anketi daha uzun ve ayrıntılı hâle getirmek', 'Yanıtları nitel olmaktan çıkarıp oran ölçeğine taşımak', 'Katılımcıların soruyu atlamasını kolaylaştırmak'], 'Dörtlü ya da altılı ölçeklerde orta nokta bulunmaz; bu, kararsız kalmaya eğilimli katılımcıların bir tarafa yönelmesini sağlar.'),
  ('Bir ölçekte bazı maddelerin olumlu (\'Matematik dersini severim\'), bazılarının olumsuz (\'Matematik dersi beni sıkar\') yazılmasının amacı nedir?', 'Düşünmeden aynı seçeneği işaretleyenleri saptamak', ['Anketin yanıtlanmasını zorlaştırıp katılımı azaltmak', 'Ölçeği sınıflama düzeyine indirmek', 'Yanıtları açık uçlu hâle getirmek'], 'Ters maddeler onaylama eğilimini ve dikkatsiz yanıtlamayı ortaya çıkarır; puanlamada bu maddeler ters çevrilir.'),
  ('Beşli bir Likert ölçeğinde \'Kesinlikle katılmıyorum\'=1 ... \'Kesinlikle katılıyorum\'=5 olarak kodlanıyor. Ters yazılmış bir maddeye \'4\' veren katılımcının puanı ters çevrildiğinde kaç olur?', '2', ['4', '−4', '3'], 'Beşli ölçekte ters puan 6 − x ile bulunur; 6 − 4 = 2.'),
  ('Bir ankette \'Hizmetimizi nasıl buldunuz? Mükemmel / Çok iyi / İyi / Orta\' seçenekleri sunuluyor. Bu ölçeğin sorunu nedir?', 'Olumsuz seçenek olmadığı için ölçek dengesizdir.', ['Seçenek sayısı çok fazla olduğu için kafa karıştırır.', 'Seçenekler sıralı olmadığı için hiç kullanılamaz.', 'Ölçek açık uçlu olduğundan yanıtlar kodlanamaz.'], 'Seçeneklerin çoğu olumlu yönde olduğunda yanıtlar yapay olarak olumluya kayar; dengeli bir ölçek olumsuz seçenekleri de içermelidir.'),
  ('Çevrimiçi anketlerde yaşlı kesimin daha az temsil edilmesi riskinin temel kaynağı nedir?', 'İnternet erişimi ve kullanımının yaşa göre farklılaşması', ['Yaşlıların hiçbir zaman ankete katılmak istememesi', 'Çevrimiçi anketlerin yalnızca açık uçlu olması', 'İnternet anketlerinde soruların sayısal olmaması'], 'İnternete erişim ve dijital beceri gruplar arasında farklı olduğunda çevrimiçi anket kapsam sorunu yaratabilir.'),
  ('Bir belediye, hem çevrimiçi hem telefonla hem de yüz yüze görüşmeyle veri topluyor. Bu karma yöntemin temel amacı nedir?', 'Farklı gruplara ulaşıp kapsamı genişletmek', ['Her katılımcıya aynı soruyu üç kez sormak', 'Anketi yalnızca internet kullanıcılarıyla sınırlamak', 'Örneklem büyüklüğünü yapay olarak küçültmek'], 'Her yöntemin ulaşamadığı gruplar farklıdır; karma yöntem kapsam ve yanıt oranını artırır.'),
  ('Pilot çalışmadan elde edilen veriler genellikle asıl çalışmanın sonuçlarına neden katılmaz?', 'Anket sonradan değiştiği için veriler karşılaştırılamaz.', ['Pilot çalışmada yalnızca nitel veri toplandığı için kullanılamaz.', 'Pilot çalışma katılımcıları her zaman yalan söylediği için güvenilmez.', 'Pilot çalışmalar yasal olarak raporlanamayan çalışmalardır.'], 'Pilot sonrasında sorular ve uygulama değiştiğinden önceki yanıtlar aynı ölçme aracından gelmemiş olur.'),
  ('Bir anket hazırlanırken soruların sıralanmasında genellikle önerilen yaklaşım hangisidir?', 'Kolay, genel sorulardan başlayıp hassas soruları sona koymak', ['Anketin ilk sorusunu en hassas soru yapmak', 'Soruları tamamen rastgele bir sırayla dizmek', 'Demografik soruları en başa koyup hassas soruları ortaya almak'], 'Katılımcının güveni ve ilgisi kolay sorularla kazanılır; gelir gibi hassas sorular genellikle sona bırakılır.'),
  ('Bir anket formunda \'Kaç kardeşiniz var?\' sorusunun hemen ardından \'Kardeşlerinizin yaşları nedir?\' sorusu geliyor. Kardeşi olmayanlar için eklenmesi gereken öğe nedir?', 'Kardeşi olmayanları ileri yönlendiren bir atlama yönergesi', ['Kardeşi olmayanların anketi bırakmasını isteyen bir uyarı', 'İkinci sorunun yanıtını zorunlu kılan bir kural', 'Bu iki soruyu tek bir soruda birleştiren bir ifade'], 'Atlama (filtre) yönergeleri, katılımcının kendisine uymayan soruları geçmesini sağlar ve anlamsız yanıtları önler.'),
  ('Bir pilot çalışmada anketin tamamlanmasının ortalama 45 dakika sürdüğü görülüyor; hedef süre 15 dakikadır. En mantıklı karar nedir?', 'Amaca hizmet etmeyen soruları çıkarıp anketi kısaltmak', ['Katılımcılara anketi daha hızlı doldurmalarını söylemek', 'Anket süresinin raporda hiç belirtilmemesi', 'Asıl uygulamada süreyi tamamen sınırsız bırakmak'], 'Uzun anket yanıt oranını ve veri kalitesini düşürür; gereksiz soruların ayıklanması en doğru çözümdür.'),
  ('Kahve içenlerle içmeyenlerin kalp sağlığını karşılaştıran bir gözlemsel çalışma, kahvenin kalp sağlığına etkisi konusunda neden-sonuç kanıtı sunmakta neden zayıftır?', 'Gruplar başka özellikler bakımından da farklı olabilir.', ['Gözlemsel çalışmalarda hiçbir veri toplanmaz.', 'Kahve tüketimi ölçülebilir bir değişken değildir.', 'Kalp sağlığı yalnızca deneylerle ölçülebilir.'], 'Kahve içenler örneğin daha çok sigara içiyor ya da daha az uyuyor olabilir; bu karıştırıcı etkenler gözlemsel çalışmada denetlenemez.'),
  ('Aşağıdaki araştırma sorularından hangisi etik nedenlerle deneyle değil, gözlemsel çalışmayla araştırılmalıdır?', 'Sigara içmenin akciğer hastalığı riskine etkisi', ['Yeni bir öğretim yönteminin sınav başarısına etkisi', 'Gübre miktarının domates verimine etkisi', 'Müzik dinlemenin kısa süreli bellek testine etkisi'], 'İnsanları zararlı olduğu bilinen bir maddeyi kullanmaya atamak etik değildir; bu yüzden sigara araştırmaları büyük ölçüde gözlemseldir.'),
  ('Deneylerde katılımcıların gruplara rastgele atanmasının temel amacı nedir?', 'Grupların başka etkenler bakımından benzer olmasını sağlamak', ['Her katılımcının uygulamayı mutlaka almasını sağlamak', 'Örneklemin anakütleden büyük olmasını sağlamak', 'Sonuçların araştırmacının beklentisine uymasını sağlamak'], 'Rastgele atama, yaş, sağlık, motivasyon gibi bilinen ve bilinmeyen etkenleri gruplar arasında şansa bağlı olarak dengeler.'),
  ('Bir öğretmen yeni yöntemi gönüllü öğrencilerle, eski yöntemi gönüllü olmayanlarla uyguluyor ve yeni yöntem grubunun daha başarılı olduğunu görüyor. Bu sonucun güvenilirliğini en çok ne zayıflatır?', 'Gruplar rastgele değil, isteğe göre oluşmuştur.', ['Grupların çok fazla öğrenciden oluşması', 'Başarının sınavla ölçülmüş olması', 'İki farklı yöntemin karşılaştırılmış olması'], 'Gönüllü öğrenciler zaten daha motive olabilir; başarı farkı yöntemden değil bu farklılıktan kaynaklanabilir.'),
  ('Bir deneyin aynı koşullarla başka araştırmacılar tarafından tekrarlanabilmesine ne ad verilir?', 'Yinelenebilirlik', ['Körleme', 'Tabakalı örnekleme ilkesi', 'Kodlama'], 'Bulguların farklı denek ve araştırmacılarla tekrarlanabilmesi sonuçların şansa bağlı olmadığına dair güven verir.'),
  ('Plasebo etkisi en iyi hangi ifadeyle açıklanır?', 'Tedavi beklentisinin gerçek iyileşme yaratabilmesi', ['Etkisiz ilacın her zaman zararlı olması', 'Kontrol grubunun hiç değişim göstermemesi', 'Gerçek ilacın plasebo almayanlarda çalışmaması'], 'Kişiler tedavi gördüklerine inandıklarında belirtilerde gerçek bir iyileşme bildirebilir; bu nedenle karşılaştırma için plasebo grubu kullanılır.'),
  ('Bir ağrı kesici deneyinde ilacı alan grubun %60\'ı, plasebo alan grubun %45\'i iyileşme bildiriyor. İlaca atfedilebilecek ek iyileşme kaç yüzde puandır?', '15', ['60', '45', '105'], 'İlacın ek etkisi iki grup arasındaki farktır: 60 − 45 = 15 yüzde puan.'),
  ('Bir araştırmada değerlendiren uzmanların hangi hastanın tedavi aldığını bilmesi neden sorun yaratabilir?', 'Beklentileri ölçümlerini etkileyebilir.', ['Uzmanlar hastalara ilaç vermeyi bırakabilir.', 'Hastaların sayısı kendiliğinden azalır.', 'Ölçümler nitel olmaktan çıkar.'], 'Bilinçli ya da bilinçsiz beklentiler, özellikle öznel ölçümlerde değerlendirmeleri tedavi grubu lehine kaydırabilir.'),
  ('Tek kör bir deneyde kim grup bilgisinden habersizdir?', 'Yalnızca katılımcılar', ['Yalnızca istatistikçiler', 'Hem katılımcılar hem araştırmacılar', 'Hiç kimse'], 'Tek körlemede genellikle katılımcılar hangi uygulamayı aldıklarını bilmez; araştırmacılar bilir.'),
  ('Boylamsal çalışmaların kesitsel çalışmalara göre en önemli üstünlüğü nedir?', 'Bireydeki değişimi izleyebilmesi', ['Çok daha kısa sürede tamamlanması', 'Katılımcı kaybının hiç olmaması', 'Maliyetinin her zaman daha düşük olması'], 'Aynı kişiler izlendiği için bireysel gelişim ve değişim doğrudan gözlemlenebilir.'),
  ('Boylamsal çalışmalarda katılımcıların zamanla çalışmadan ayrılmasına ne ad verilir ve bu neden önemlidir?', 'Katılımcı kaybı; kalanlar farklılaşabilir.', ['Kota hatası; örneklem otomatik olarak büyür.', 'Kapsam fazlalığı; çerçeve gereksiz kişileri içerir.', 'Plasebo etkisi; kalanlar tedaviye inanır.'], 'Çalışmadan ayrılanlar rastgele değilse (örneğin sağlığı kötüleşenler), geride kalan grup başlangıçtaki örneklemi temsil etmez.'),
  ('Bir seçim anketi sonucunun yanında \'±3 puan hata payı\' yazıyor. Bu ifade en çok neyi anlatır?', 'Şansa bağlı belirsizliğin büyüklüğünü', ['Anketi yapan şirketin hata yapma olasılığını', 'Yanıt vermeyenlerin oranını', 'Soruların yönlendirici olma derecesini'], 'Hata payı rastgele örneklemeden kaynaklanan belirsizliği gösterir; yanlı soru ya da yanıtsızlık gibi örnekleme dışı hataları kapsamaz.'),
  ('Bir anket %52 destek buluyor ve hata payı ±4 puan. Bu sonuç için en yerinde yorum hangisidir?', 'Gerçek destek %50\'nin altında da olabilir.', ['Gerçek destek kesinlikle %52\'dir.', 'Gerçek destek kesinlikle %50\'nin üzerindedir.', 'Gerçek destek %4 ile %52 arasındadır.'], 'Hata payı dikkate alındığında makul aralık yaklaşık %48–%56\'dır; bu aralık %50\'nin altını da içerir.'),
  ('Örnekleme dışı hata kavramına aşağıdakilerden hangisi örnek olarak verilebilir?', 'Bir görüşmecinin yanıtları yanlış kaydetmesi', ['İki rastgele örneklemin ortalamalarının farklı çıkması', 'Örneklem küçükken tahminlerin daha çok dalgalanması', 'Rastgele seçilen kişilerin şans eseri genç çıkması'], 'Kayıt hataları, yanlı sorular ve yanıtsızlık örnekleme dışı hatalardır; örneklemler arası şans farkı ise örnekleme hatasıdır.'),
  ('Bir ankette eksik yanıtı olan katılımcıların hepsi analizden çıkarılıyor. Eksik yanıt verenler daha çok belirli bir gruptansa ne olur?', 'Kalan veri yanlı olabilir.', ['Sonuçlar her durumda daha doğru olur.', 'Örnekleme hatası sıfıra iner.', 'Veri nitel olmaktan çıkar.'], 'Eksiklik rastgele değilse, eksik kişileri silmek belirli bir grubu az temsil eder ve sonuçları çarpıtır.'),
  ('Veri setindeki aykırı bir değerin doğru ölçülmüş gerçek bir değer olduğu doğrulanmışsa ne yapılmalıdır?', 'Silinmemeli, analizde dikkate alınmalıdır.', ['Mutlaka veri setinden silinmelidir.', 'Ortalamaya eşit bir değerle değiştirilmelidir.', 'Diğer değerlerle aynı olacak şekilde yuvarlanmalıdır.'], 'Gerçek uç değerler verinin doğal parçasıdır; yalnızca \'uygunsuz\' göründükleri için silmek sonuçları çarpıtır.'),
  ('Bir anket verisinde eksik değerler \'999\' koduyla gösterilmiş. Bu kodu fark etmeden yaş ortalaması hesaplanırsa ne olur?', 'Ortalama gerçeğinden büyük çıkar.', ['Ortalama gerçeğinden küçük çıkar.', 'Ortalama bu koddan hiç etkilenmez, aynı kalır.', 'Ortalama tam olarak sıfır çıkar.'], '999 gerçek bir yaş değeri gibi hesaba katılırsa ortalamayı çok yukarı çeker; eksik veri kodları analiz öncesinde tanımlanmalıdır.'),
  ('Bir öğretmen 30 öğrencinin ulaşım biçimini kaydediyor: yürüyerek 12, servisle 9, toplu taşımayla 6, özel araçla 3. Bu verilerden çıkarılabilecek kesin yargı hangisidir?', 'Yürüyerek gelenler, toplu taşıma ve özel araç kullananların toplamından fazladır.', ['Servisle gelenler sınıfın yarısından fazladır.', 'Özel araçla gelenler yürüyenlerin yarısıdır.', 'Toplu taşıma kullananlar servis kullananlardan fazladır.'], 'Toplu taşıma ve özel araç toplamı 6 + 3 = 9\'dur ve 12\'den azdır; diğer yargılar verilerle çelişir.'),
  ('Bir kitapçı bir günde sattığı kitapları türlerine göre sayıyor: roman 18, şiir 4, tarih 9, bilim 9. Bu verilerle ilgili hangisi doğrudur?', 'Bir günde toplam 40 kitap satılmıştır.', ['Tarih kitapları bilim kitaplarından fazla satılmıştır.', 'Şiir kitapları tüm satışların dörtte birini oluşturur.', 'Romanlar diğer türlerin toplamından fazla satılmıştır.'], 'Toplam 18 + 4 + 9 + 9 = 40\'tır. Romanlar 18, diğerlerinin toplamı 22\'dir; şiir payı 4/40 = %10\'dur.'),
  ('Bir anketin frekans dağılımında kategorilerin frekansları 12, 15, 9 ve 14 olarak verilmiş; ancak ankete 52 kişi katıldığı biliniyor. Bu durum ne anlama gelir?', 'İki kişinin yanıtı kayıtlarda yer almıyor.', ['Katılımcı sayısı kesinlikle yanlış yazılmıştır.', 'Kategorilerden birinin frekansı iki kez sayılmıştır.', 'Toplamlar arasında hiçbir fark yoktur.'], 'Frekansların toplamı 50\'dir; 52 − 50 = 2 yanıt eksik ya da geçersiz olarak ayrılmış olmalıdır.'),
  ('A okulunda 200 öğrenciden 50\'si, B okulunda 600 öğrenciden 120\'si satranç kulübüne üyedir. Hangi yargı doğrudur?', 'Üyelik oranı A okulunda daha yüksektir.', ['Üyelik oranı B okulunda daha yüksektir.', 'İki okulda üyelik oranı aynıdır.', 'Okul büyüklükleri farklı olduğu için oranlar karşılaştırılamaz.'], 'A\'da oran 50/200 = %25, B\'de 120/600 = %20\'dir; sayı fazla olsa da oran A\'da yüksektir.'),
  ('Bir sınıfta öğrencilerin %40\'ı kız ve kız öğrenci sayısı 14\'tür. Sınıfta toplam kaç öğrenci vardır?', '35', ['56', '28', '5,6'], '14 öğrenci toplamın %40\'ı ise toplam 14 / 0,40 = 35\'tir.'),
  ('Bir ankette katılımcıların %25\'i A, %35\'i B seçeneğini işaretliyor; geri kalan 120 kişi C seçeneğini işaretliyor. Ankete kaç kişi katılmıştır?', '300', ['400', '171,4', '480'], 'C\'yi seçenlerin payı %100 − %60 = %40\'tır; 120 / 0,40 = 300 kişi.'),
  ('Bir öğretmen \'Geçen yıl kulübe 20 öğrenci katıldı, bu yıl 30 öğrenci katıldı.\' diyor. Katılımdaki yüzde artış kaçtır?', '%50', ['%10', '%33', '%150'], 'Artış 10 öğrencidir; 10 / 20 = 0,5, yani %50 artış.'),
  ('Bir dağılımda birikimli frekanslar sırasıyla 5, 13, 24, 30 olarak verilmiştir. Üçüncü kategorinin kendi frekansı kaçtır?', '11', ['24', '8', '6'], 'Bir kategorinin frekansı ardışık birikimli frekansların farkıdır: 24 − 13 = 11.'),
  ('Bir dağılımda birikimli göreli frekanslar 0,15; 0,40; 0,80; 1,00 biçimindedir. Gözlemlerin yüzde kaçı ikinci kategoriden sonraki kategorilerdedir?', '%60', ['%40', '%80', '%20'], 'İlk iki kategoride %40 vardır; geri kalan 1 − 0,40 = 0,60, yani %60\'tır.'),
  ('Bir koşu yarışında 60 koşucunun bitirme süreleri gruplanıyor: 30 dk altı 8, 30–39 dk 21, 40–49 dk 19, 50 dk ve üstü 12. 50 dakikadan kısa sürede bitiren koşucu sayısı kaçtır?', '48', ['40', '19', '29'], '8 + 21 + 19 = 48 koşucu 50 dakikadan önce bitirmiştir; ya da 60 − 12 = 48.'),
  ('Bir öğrenci birikimli frekansları hesaplarken 4, 9, 7, 15 değerlerini buluyor. Bu sonuçta kesin bir hata olduğu nereden anlaşılır?', 'Birikimli frekans hiç azalamaz.', ['İlk değer her zaman sıfır olmalıdır.', 'Son değer her zaman 100 olmalıdır.', 'Değerler tek sayı olamaz.'], 'Frekanslar negatif olamayacağından birikimli frekans azalmayan bir dizidir; 9\'dan 7\'ye düşüş bir hesap hatasıdır.'),
  ('Bir sınıfın sınav puanları için \'x puandan az alan öğrenci sayısı\' şöyle verilmiş: 40\'tan az 3, 60\'tan az 11, 80\'den az 23, 100\'den az 28. 60 ile 79 arasında puan alan kaç öğrenci vardır?', '12', ['23', '8', '5'], '80\'den az alanlar 23, 60\'tan az alanlar 11\'dir; aradaki fark 23 − 11 = 12 öğrencidir.'),
  ('Gruplanmış bir frekans dağılımında 20–29 sınıfının alt sınırı, üst sınırı ve genişliği (tam sayı veriler için) nedir?', '20, 29 ve 10', ['20, 29 ve 9', '20, 30 ve 9 birim', '29, 20 ve 10'], 'Tam sayı verilerde 20–29 sınıfı 20, 21, ..., 29 olmak üzere 10 değer içerir; genişlik 10\'dur.'),
  ('Bir veri setinde en küçük değer 12, en büyük değer 87\'dir. Veriler eşit genişlikte 8 sınıfa ayrılacaksa sınıf genişliği en az kaç olmalıdır (tam sayı)?', '10', ['9,375', '8', '75'], 'Açıklık 87 − 12 = 75\'tir; 75 / 8 = 9,375 olduğundan genişlik yukarı yuvarlanarak 10 alınır.'),
  ('Gruplanmış frekans dağılımı hazırlamanın başlıca sakıncası nedir?', 'Tek tek değerlerin bilgisinin kaybolması', ['Gözlem sayısının artması', 'Verilerin nitel veriye dönüşmesi', 'Frekansların toplamının değişmesi'], 'Değerler sınıflara toplandığında bir sınıf içindeki gözlemlerin tam değerleri artık görülmez.'),
  ('Bir öğrenci boy verilerini \'150–160, 160–170, 170–180\' biçiminde sınıflara ayırıyor. 160 cm boyundaki bir öğrenci için bu düzenlemenin sorunu nedir?', 'Hangi sınıfa gireceği belirsizdir.', ['Bu öğrenci dağılımdaki hiçbir sınıfa yerleştirilemez.', 'Sınıf genişlikleri farklıdır.', 'Sınıf sayısı çok fazladır.'], 'Sınır değerleri iki sınıfta birden yer aldığında gözlemlerin nereye yazılacağı belirsizleşir; \'150–159, 160–169\' ya da \'150 ≤ x < 160\' gibi bir kural gerekir.'),
  ('Bir dağılımda sınıflar 0–9, 10–19, 20–39, 40–79 olarak belirlenmiş. Bu sınıflandırmanın dikkat edilmesi gereken özelliği nedir?', 'Sınıf genişlikleri eşit değildir.', ['Sınıflar birbiriyle çakışmaktadır.', 'Sınıflar arasında boşluk vardır.', 'Sınıflar azalan sırada dizilmiştir.'], 'Genişlikler 10, 10, 20 ve 40\'tır; eşit olmayan genişlikler frekansların karşılaştırılmasında dikkat gerektirir.'),
  ('50 öğrencinin aylık kitap okuma sayıları gruplanırken çok az (örneğin 2) sınıf kullanılırsa ne olur?', 'Dağılımın biçimi görülemez.', ['Her değer ayrı bir sınıfa düşer.', 'Frekansların toplamı 50\'den fazla olur.', 'Veriler kendiliğinden sıralı nitel veriye dönüşür.'], 'Çok az sınıf, ayrıntıları tek gruplarda birleştirir ve dağılımın şeklini gizler; çok fazla sınıf ise dağılımı parçalı gösterir.'),
  ('Bir araştırmacının 25 kişilik verisi şöyle gruplanmış: 10–19: 4, 20–29: 9, 30–39: 7, 40–49: 5. 30 yaşından küçüklerin oranı yüzde kaçtır?', '%52', ['%5,2', '%13', '%64'], '30 yaşından küçükler 4 + 9 = 13 kişidir; 13 / 25 = %52.'),
  ('Bir sütun grafiği beş günlük ziyaretçi sayılarını gösteriyor: pazartesi 40, salı 55, çarşamba 35, perşembe 60, cuma 50. Bir önceki güne göre ziyaretçi sayısının azaldığı günler hangileridir?', 'Çarşamba ve cuma', ['Salı ve perşembe', 'Yalnızca çarşamba', 'Pazartesi ve cuma'], 'Salıdan çarşambaya 55\'ten 35\'e, perşembeden cumaya 60\'tan 50\'ye düşüş vardır.'),
  ('Bir okulun dört kulübünün üye sayılarını gösteren sütun grafiğinde sütunlar bitişik değil, aralarında boşluk bırakılarak çizilmiştir. Bunun nedeni nedir?', 'Kategoriler ayrık ve sırasızdır.', ['Verilerin sürekli olduğunu belirtmek için', 'Kulüplerin üye sayısının sıfır olduğunu göstermek için', 'Eksenin ölçeğinin değiştiğini göstermek için'], 'Kategorik verilerde sütunlar arası boşluk, kategoriler arasında sürekli bir sayı doğrusu olmadığını vurgular; histogramda ise sütunlar bitişiktir.'),
  ('Bir sütun grafiğine göre bir kantinde satılan ürünler: tost 45, simit 30, su 75, meyve suyu 50 adet. Satılan su sayısı, tost ve simidin toplamına göre nasıldır?', 'Eşittir.', ['15 adet fazladır.', '15 adet azdır.', 'İki katıdır.'], 'Tost ve simit toplamı 45 + 30 = 75\'tir; satılan su da 75 adettir.'),
  ('Bir sütun grafiğinde yatay sütunlar (çubuklar) kullanılarak ülkelerin adları gösteriliyor. Yatay çubuk tercihinin en olası nedeni nedir?', 'Uzun kategori adlarını okunur kılmak', ['Verilerin zaman serisi olduğunu göstermek', 'Sütunların toplamının 100 olduğunu göstermek', 'Değerlerin negatif olduğunu belirtmek'], 'Kategori adları uzun olduğunda yatay çubuk grafiği etiketlerin rahat yazılmasını sağlar.'),
  ('Bir sütun grafiği 2015–2019 yılları arasında bir kütüphanenin ödünç verdiği kitap sayılarını gösteriyor: 2015: 800, 2016: 950, 2017: 1100, 2018: 1050, 2019: 1300. Bir önceki yıla göre en büyük artış hangi yılda olmuştur?', '2019', ['2016', '2017', '2018'], 'Artışlar: 2016\'da 150, 2017\'de 150, 2018\'de −50, 2019\'da 250\'dir; en büyük artış 2019\'dadır.'),
  ('Bir sütun grafiğinde her sütunun üzerine sayısal değer yazılmamış ve dikey eksende yalnızca 0 ile 100 işaretli. Bu grafiğin okunmasındaki temel güçlük nedir?', 'Değerler ancak yaklaşık kestirilebilir.', ['Kategoriler birbirinden ayırt edilemez.', 'Sütunların toplamı bilinemez hâle gelir.', 'Grafik kategorik veri için kullanılamaz.'], 'Ara değer çizgileri ve etiketler olmadığında sütun yükseklikleri yalnızca göz kararı tahmin edilebilir.'),
  ('Bir ankette 600 kişiden 150\'si A, 250\'si B, kalanı C seçeneğini işaretliyor. C seçeneğinin daire grafiğindeki dilim açısı kaç derecedir?', '120°', ['150°', '200°', '100°'], 'C\'yi seçenler 600 − 400 = 200 kişidir; 200 / 600 · 360 = 120°.'),
  ('Bir daire grafiğinde \'spor\' dilimi 72° ve bu dilim 40 öğrenciyi gösteriyor. Ankete kaç öğrenci katılmıştır?', '200', ['72', '2880', '360'], '72° tam dairenin 72/360 = 1/5\'idir; 40 öğrenci toplamın beşte biri ise toplam 200\'dür.'),
  ('Bir okulun 720 öğrencisinin ulaşım tercihleri daire grafiğiyle gösteriliyor. Servis dilimi 150° ise servisle gelen öğrenci sayısı kaçtır?', '300', ['150', '250', '432,5'], '150/360 · 720 = 300 öğrenci.'),
  ('Bir daire grafiğinde 8 kategoriden 5\'i çok küçük dilimlerden oluşuyor ve etiketleri okunamıyor. Bu sorunun en uygun çözümü hangisidir?', 'Küçük kategorileri \'diğer\' altında toplamak', ['Küçük dilimleri grafikten tamamen silmek', 'Dilimlere rastgele renk vermek', 'Daire grafiğini üç boyutlu çizmek'], 'Çok sayıda küçük dilim okunabilirliği bozar; küçük kategorileri birleştirmek ya da sütun grafiği kullanmak daha anlaşılır olur.'),
  ('Üç boyutlu ve eğik çizilmiş bir daire grafiğinin okuyucuyu yanıltabilmesinin nedeni nedir?', 'Öndeki dilimler büyük görünür.', ['Dilim açılarının toplamı 360° olmaktan çıkar.', 'Renkler yüzünden kategoriler karışır ve ayırt edilemez.', 'Grafikteki yüzdeler otomatik olarak değişir ve bozulur.'], 'Perspektif etkisi öne yakın dilimleri büyütür, arkadakileri küçültür; bu da göze yanlış oranlar yansıtır.'),
  ('Bir çizgi grafiği bir hastanın 6 saatlik ateş ölçümlerini gösteriyor (°C): 38,2; 38,9; 39,4; 38,7; 38,0; 37,4. Ateşin en yüksek olduğu ölçüm kaçıncıdır ve sonrasında nasıl bir eğilim vardır?', '3. ölçüm, sonra sürekli düşüş', ['2. ölçüm, sonra sürekli yükseliş', '3. ölçüm, sonra önce artış sonra düşüş', '6. ölçüm, öncesinde sürekli düşüş'], 'En yüksek değer 39,4 ile 3. ölçümdedir; ardından 38,7, 38,0 ve 37,4 ile sürekli azalır.'),
  ('Bir mağazanın satışlarını gösteren çizgi grafiğinde her yıl aralık ayında belirgin bir tepe, ocak ayında ise düşüş görülüyor. Bu düzene ne ad verilir?', 'Mevsimsellik', ['Rastgele gürültü', 'Kapsam hatası', 'Kota etkisi'], 'Belirli dönemlerde düzenli olarak yinelenen dalgalanmalar zaman serilerinde mevsimsellik olarak adlandırılır.'),
  ('Bir çizgi grafiğinde bir şirketin hisse fiyatı 10 yılda 20 TL\'den 80 TL\'ye çıkıyor. Dikey eksen doğrusal ise başlangıçtan sona toplam artış yüzde kaçtır?', '%300', ['%400', '%60', '%75'], 'Artış 60 TL\'dir; 60 / 20 = 3, yani %300 artış.'),
  ('Bir histogramda öğrencilerin boyları gösteriliyor: 150–159 cm: 4, 160–169 cm: 11, 170–179 cm: 8, 180–189 cm: 2. Öğrencilerin yüzde kaçı 170 cm ve üzerindedir?', '%40', ['%32', '%60', '%8'], '170 ve üzeri 8 + 2 = 10 öğrencidir; toplam 25\'tir; 10/25 = %40.'),
  ('Bir histogramda sütunların çoğu sol tarafta toplanmış ve sağa doğru uzun bir kuyruk uzanıyor. Bu dağılım biçimine ne ad verilir?', 'Sağa çarpık', ['Sola çarpık', 'Simetrik', 'Tekdüze'], 'Kuyruk sağa doğru uzanıyorsa dağılım sağa (pozitif) çarpıktır; gelir dağılımları buna sık görülen bir örnektir.'),
  ('Bir histogramda iki belirgin tepe görülüyor. Bu durumun olası bir açıklaması hangisidir?', 'Verilerin iki farklı gruptan gelmesi', ['Verilerin tamamının aynı değerde olması', 'Histogramın yanlışlıkla daire grafiği gibi çizilmesi', 'Verilerin hiç değişkenlik göstermemesi'], 'İki tepeli dağılım çoğu zaman iki alt grubun (örneğin iki yaş grubu) karışımını işaret eder.'),
  ('Aynı verinin iki histogramı çiziliyor: birinde 3, diğerinde 30 sınıf kullanılıyor. Hangi ifade doğrudur?', 'Sınıf sayısı dağılımın görünümünü değiştirir.', ['İki histogram her zaman tamamen aynı görünür.', 'Çok sınıflı histogramda gözlem sayısı artar.', 'Az sınıflı histogramda veriler nitel hâle gelir.'], 'Az sınıf ayrıntıyı gizler, çok sınıf ise dağılımı parçalı ve gürültülü gösterir; uygun sınıf sayısı seçmek önemlidir.'),
  ('Bir histogram bir sınavdaki puanları gösteriyor ve 90–100 sınıfında çok yüksek bir sütun, diğer sınıflarda düşük sütunlar var. Bu dağılım için en uygun yorum hangisidir?', 'Sınav öğrencilerin çoğu için kolaydı.', ['Sınav öğrencilerin çoğu için çok zordu.', 'Puanlar sınıflara eşit olarak dağılmıştır.', 'Puanlar sağa doğru uzun bir kuyruk oluşturmuştur.'], 'Puanlar üst uçta yığılmıştır; bu, sola çarpık bir dağılımdır ve sınavın kolay olduğunu düşündürür.'),
  ('Bir nokta grafiği 20 öğrencinin bir haftada izlediği film sayısını gösteriyor: 0 film 2 nokta, 1 film 5 nokta, 2 film 7 nokta, 3 film 4 nokta, 4 film 2 nokta. Öğrencilerin toplam kaç film izlediği hesaplanabilir mi, hesaplanırsa kaçtır?', 'Evet, 39', ['Evet, 20', 'Hayır, hesaplanamaz', 'Evet, 10'], 'Toplam = 0·2 + 1·5 + 2·7 + 3·4 + 4·2 = 0 + 5 + 14 + 12 + 8 = 39.'),
  ('Nokta grafiği en çok hangi durumda kullanışlıdır?', 'Küçük bir sayısal veri setinde', ['Milyonlarca gözlemden oluşan veri setlerinde', 'Bir bütünün parçalarının açısını göstermede', 'İki kategorik değişkenin ilişkisini göstermede'], 'Her gözlemin bir noktayla gösterildiği nokta grafiği az sayıda gözlem için açık ve okunaklıdır.'),
  ('Bir nokta grafiğinde değerler 1 ile 10 arasında yayılıyor; 2–4 arasında çok nokta toplanmış, 9\'da ise tek bir nokta var. 9\'daki nokta için en uygun ifade hangisidir?', 'Diğerlerinden uzak, aykırı olabilecek bir değer', ['Verilerin çoğunun toplandığı bölge', 'Hata olduğu kesin olan bir değer', 'Verinin tekdüze dağıldığının kanıtı'], 'Diğer gözlemlerden belirgin biçimde uzakta duran tek nokta olası bir aykırı değerdir; hata olup olmadığı ayrıca denetlenmelidir.'),
  ('Bir nokta grafiğinde 1, 2, 3, 4 ve 5 puan değerlerinin üzerinde sırasıyla 1, 3, 6, 3 ve 1 nokta var. Bu dağılımın biçimi için hangisi en uygundur?', 'Simetrik, tek tepeli', ['Sağa çarpık', 'Sola çarpık', 'İki tepeli'], 'Frekanslar 3 puanın iki yanında aynı biçimde azalır (1-3-6-3-1); dağılım simetrik ve tek tepelidir.'),
  ('Bir gövde-yaprak gösterimi şöyle: 1 | 3 8, 2 | 0 4 4 9, 3 | 1 5, 4 | 7 (gövde onlar, yaprak birler). Kaç değer 25\'ten büyüktür?', '4', ['3', '5', '10'], '25\'ten büyükler: 29, 31, 35, 47; toplam 4 değer.'),
  ('Gövde-yaprak gösteriminin histograma göre önemli bir avantajı nedir?', 'Tek tek değerleri korur.', ['Çok büyük veri setleri için daha kullanışlıdır.', 'Kategorik verileri daha iyi gösterir.', 'Yüzdeleri doğrudan gösterir.'], 'Gövde-yaprak gösteriminde her gözlemin değeri okunabilir; histogramda değerler sınıflar içinde kaybolur.'),
  ('Bir gövde-yaprak gösteriminde \'7 | 0 0 3\' satırı ve \'Anahtar: 7 | 3 = 7,3\' notu var. Bu satırda hangi değerler vardır?', '7,0; 7,0; 7,3', ['70, 70, 73', '7, 0, 0, 3', '700, 703'], 'Anahtar, gövdenin birler, yaprağın ondalık basamağı olduğunu gösterir: 7,0; 7,0 ve 7,3.'),
  ('Bir öğrenci gövde-yaprak gösteriminde yaprakları sıralamadan yazıyor: 3 | 8 1 5. Bu durum hangi bilgiyi zorlaştırır?', 'Değerlerin sırasını görmeyi', ['Gözlem sayısını bulmayı', 'Gövdenin anlamını belirlemeyi', 'Değerlerin ondalıklı olup olmadığını'], 'Yapraklar sıralı yazılmadığında değerlerin sırası bir bakışta görülemez; gösterim yine de değerleri doğru içerir.'),
  ('İki sınıfın puanları sırt sırta gövde-yaprak gösterimiyle veriliyor. Bu düzenin amacı nedir?', 'İki grubun dağılımını karşılaştırmak', ['İki grubun verilerini birbirine eklemek', 'Yaprakları rastgele sıralamak', 'Gövdeleri iki katına çıkarmak'], 'Ortak gövdenin iki yanına iki grubun yaprakları yazılır; böylece dağılımların biçimi yan yana karşılaştırılabilir.'),
  ('Bir kutu grafiğinde bıyıkların dışında tek tek işaretlenmiş noktalar neyi gösterir?', 'Olası aykırı değerleri', ['Ortanca değerleri', 'Çeyrekleri', 'Eksik verileri'], 'Kutu grafiklerinde belirli bir kurala göre bıyık sınırlarının dışında kalan gözlemler ayrı noktalarla gösterilir; bunlar olası aykırı değerlerdir.'),
  ('İki sınıfın sınav puanlarının kutu grafikleri yan yana çizilmiş. A sınıfının kutusu 60–70, B sınıfının kutusu 45–85 arasında. Bu bilgiye göre hangisi doğrudur?', 'B\'de orta yarı daha geniş yayılmıştır.', ['A sınıfında puanlar daha geniş bir alana yayılmıştır.', 'İki sınıfın puanlarının yayılımı tamamen aynıdır.', 'B sınıfında hiçbir öğrenci 60 ile 70 arasında puan almamıştır.'], 'Kutu uzunluğu verilerin ortadaki yarısının yayılımını gösterir; B\'nin kutusu (40 puan) A\'nınkinden (10 puan) çok daha uzundur.'),
  ('Resimli grafiklerin önemli bir sınırlılığı nedir?', 'Kesirli simgelerle kesin değer zor okunur.', ['Yalnızca sayısal sürekli veriler için kullanılabilmesi', 'Kategorik verilerle hiç kullanılamaması', 'Her zaman üç boyutlu çizilmek zorunda olması'], 'Yarım ya da çeyrek simgeler göz kararıyla yorumlanır; bu da kesin değerlerin okunmasını zorlaştırır.'),
  ('Bir resimli grafik hazırlanırken simge değerinin (bir simgenin temsil ettiği miktar) seçimi neden önemlidir?', 'Simge sayısını makul düzeyde tutmak için', ['Simgelerin renklerini belirlemek için', 'Grafiğin başlığını kısaltmak için', 'Kategorilerin sırasını belirlemek için'], 'Çok küçük bir simge değeri yüzlerce simge, çok büyük bir değer ise okunması zor kesirli simgeler doğurur.'),
  ('Bir grafiğin dikey ekseninde kesik eksen işaretinin (zikzak) bulunması neden önemlidir?', 'Eksenin sıfırdan başlamadığını bildirir.', ['Grafiğin çizilmesinin tamamlanmadığını gösterir.', 'Verilerin eksik olduğunu kesin olarak kanıtlar.', 'Değerlerin negatif olduğunu belirtir.'], 'Kesik eksen işareti okuyucuyu uyararak sütun boylarının oransal olarak karşılaştırılmaması gerektiğini hatırlatır.'),
  ('İki grafik aynı veriyi gösteriyor; birinde dikey eksen 0–100, diğerinde 0–1000 arasında. Değerler 40 ile 60 arasındaysa ikinci çizimde ne görülür?', 'Değişim neredeyse düz bir çizgi gibi görünür.', ['Değişim çok büyük ve dramatik görünür.', 'Değerler negatifmiş gibi görünür.', 'İki grafik tamamen aynı görünür.'], 'Gereksiz geniş eksen aralığı farkları ezer; gerçek bir değişim önemsiz gibi görünür.'),
  ('Bir grafik üzerinde yalnızca son üç ayın verisi gösterilerek \'satışlar sürekli artıyor\' iddiası destekleniyor; oysa önceki dokuz ayda belirgin bir düşüş vardı. Bu yanıltma tekniğine ne ad verilebilir?', 'Seçici zaman aralığı kullanmak', ['Kesik eksen kullanmak', 'Üç boyutlu dilim çizmek', 'Simgeleri büyütmek'], 'Uygun olmayan başlangıç noktası seçmek genel eğilimi gizleyip istenen sonuca uygun bir görüntü yaratır.'),
  ('Bir sütun grafiğinde sütunlar arasındaki aralıklar eşit değil ve bazı sütunlar diğerlerinden geniş çizilmiş. Bu durum neden yanıltıcı olabilir?', 'Göz, sütunların alanını karşılaştırır.', ['Sütunların rengi farklı göründüğü için', 'Kategorilerin adları okunamadığı için', 'Eksenin ölçeği kesin olarak değiştiği için'], 'Kategorik sütun grafiğinde değer yalnızca yükseklikle gösterilmelidir; geniş sütunlar daha büyük alan kapladığından daha büyük algılanır.'),
  ('Bir anket katılımcıların en sevdiği müzik türünü (pop, rock, klasik, türkü, rap) soruyor. Bu sonuçları göstermek için hangisi uygun bir seçim değildir?', 'Çizgi grafiği', ['Sütun grafiği', 'Daire grafiği', 'Yatay çubuk grafiği'], 'Müzik türleri sırasız kategorilerdir; çizgi grafiği noktalar arasında süreklilik ima ettiği için uygun değildir.'),
  ('Bir araştırmacı 5 ülkenin 2000–2020 yılları arasındaki yıllık nüfus artışını tek bir çizimde karşılaştırmak istiyor. En uygun seçim hangisidir?', 'Her ülke için bir çizginin olduğu çok çizgili grafik', ['Her yıl için ayrı bir daire grafiği', 'Tek bir histogram', 'Gövde-yaprak gösterimi'], 'Çok çizgili grafik birden fazla zaman serisini aynı eksende karşılaştırmaya olanak tanır.'),
  ('Bir okulun dört şubesinde kız ve erkek öğrenci sayılarını aynı anda karşılaştırmak için en uygun grafik hangisidir?', 'Gruplanmış sütun grafiği', ['Tek bir daire grafiği', 'Histogram', 'Tek çizgili grafik'], 'Gruplanmış sütun grafiği her şube için kız ve erkek sütunlarını yan yana göstererek iki kategorik değişkeni birlikte karşılaştırır.'),
  ('Bir okulda kızlardan 70\'i evet, 30\'u hayır; erkeklerden 55\'i evet, 45\'i hayır diyerek kahvaltı sorusunu yanıtlıyor. Kahvaltı yapan öğrencilerin yüzde kaçı kızdır?', '%56', ['%70', '%35', '%62,5'], 'Kahvaltı yapanlar 125 kişidir; bunların 70\'i kızdır: 70 / 125 = %56.'),
  ('İki yönlü bir sıklık dağılımında \'marjinal (kenar) toplamlar\' neyi gösterir?', 'Her satır ve sütunun toplamını', ['Yalnızca en büyük hücre değerini', 'Hücrelerin ortalamasını', 'Satır ve sütun sayısını'], 'Kenar toplamları her bir değişkenin tek başına dağılımını verir; satır ve sütun toplamlarından oluşur.'),
  ('Bir araştırmada 300 yetişkine spor yapıp yapmadıkları ve sigara içip içmedikleri soruluyor: spor yapan ve sigara içen 20, spor yapan ve içmeyen 130, spor yapmayan ve içen 60, spor yapmayan ve içmeyen 90. Sigara içenlerin yüzde kaçı spor yapar?', '%25', ['%20', '%13,3', '%40'], 'Sigara içenler 20 + 60 = 80 kişidir; bunların 20\'si spor yapar: 20/80 = %25.'),
  ('İki yönlü bir sıklık dağılımında \'koşullu göreli frekans\' nasıl hesaplanır?', 'Hücre sıklığı bölü o satırın ya da sütunun toplamı', ['Hücre sıklığı bölü hücre sayısı', 'Satır toplamı bölü sütun sayısı', 'Hücre sıklığı çarpı genel toplam'], 'Koşullu göreli frekans, belirli bir grup içindeki payı gösterir; bu yüzden payda o grubun toplamıdır.'),
  ('Yüzde yığılmış sütun grafiğinde bütün sütunların yüksekliği neden aynıdır?', 'Her sütun %100\'ü gösterir.', ['Her kategoride gözlem sayısı aynıdır.', 'Grafik hatalı çizilmiştir.', 'Her alt grup aynı değeri alır.'], 'Yüzde yığılmış grafikte her sütun kendi bütününe göre ölçeklenir; karşılaştırma yalnızca paylar üzerindendir.'),
  ('Bir gruplanmış sütun grafiği üç yıl boyunca iki kentin turist sayısını gösteriyor (bin): 2016 A 40, B 55; 2017 A 50, B 52; 2018 A 65, B 48. Hangi yıl A kenti B\'yi ilk kez geçmiştir?', '2018', ['2016', '2017', 'Hiç geçmemiştir'], '2016 ve 2017\'de A, B\'nin altındadır; 2018\'de 65 > 48 olur.'),
  ('Bir sütun grafiğinde dört kategori 10, 20, 30 ve 60 değerlerini gösteriyor. Aynı veri daire grafiğine dönüştürülürse 60 değerli kategorinin açısı kaç derece olur?', '180°', ['60°', '120°', '216°'], 'Toplam 120\'dir; 60 / 120 = 1/2, yani 180°.'),
  ('Bir daire grafiğinde A 90°, B 135°, C 135° olarak verilmiştir. Toplam 400 kişi ise aynı veriyi sütun grafiğiyle gösterirken B sütununun yüksekliği kaç kişi olmalıdır?', '150', ['135', '100', '112,5'], '135 / 360 · 400 = 150 kişi.'),
  ('Bir frekans dağılımından elde edilen göreli frekanslar 0,1; 0,3; 0,4; 0,2\'dir. Bu veri daire grafiğine aktarılırsa açılar sırasıyla kaç derece olur?', '36°, 108°, 144°, 72°', ['10°, 30°, 40°, 20°', '90°, 90°, 90°, 90°', '36°, 72°, 108°, 144°'], 'Her göreli frekans 360 ile çarpılır: 36°, 108°, 144°, 72°.'),
  ('Bir gövde-yaprak gösteriminden histogram çizilecekse her gövde satırı neye karşılık gelir?', 'Bir sınıf aralığına', ['Bir tek gözleme', 'Bir yüzde değerine', 'Bir dilim açısına'], 'Gövde satırları, örneğin 20–29, 30–39 gibi eşit genişlikte sınıflara karşılık gelir; yaprak sayısı da sütun yüksekliğini verir.'),
  ('18 yaşından küçük öğrencilerle yapılacak bir anket için etik açıdan genellikle ne gereklidir?', 'Veli onayı ve öğrencinin kendi rızası', ['Yalnızca öğretmenin izni', 'Yalnızca okul müdürünün sözlü onayı', 'Hiçbir izin gerekmez'], 'Reşit olmayanlarla yapılan araştırmalarda yasal vasinin onayı ve çocuğun kendi kabulü birlikte aranır.'),
  ('Anonimlik ile gizlilik arasındaki fark nedir?', 'Anonimlikte kimlik hiç bilinmez; gizlilikte bilinir ama açıklanmaz.', ['Anonimlik yalnızca deneylerde, gizlilik yalnızca anketlerde kullanılır.', 'İkisi tamamen aynı anlama gelir.', 'Gizlilik, verilerin herkese açık yayımlanmasıdır.'], 'Anonim çalışmada araştırmacı bile yanıtı kimin verdiğini bilmez; gizli çalışmada bilir ama kimliği korur.'),
  ('Bir okul anketinin sonuçları raporlanırken \'9-C şubesindeki tek yabancı uyruklu öğrenci ...\' gibi bir ifade kullanılıyor. Bu ifadenin etik sorunu nedir?', 'Kişiyi tanınır hâle getirmesi', ['Örneklem büyüklüğünü değiştirmesi', 'Yanıtsızlık yanlılığı yaratması', 'Soruyu yönlendirici yapması'], 'Ad yazılmasa bile çok küçük gruplara ilişkin ayrıntılar kişinin kimliğini ortaya çıkarabilir; bu gizliliği ihlal eder.'),
  ('Bir araştırmacının yalnızca hipotezini destekleyen verileri raporlayıp desteklemeyenleri gizlemesi hangi etik sorundur?', 'Verileri seçici raporlama', ['Bilgilendirilmiş onam', 'Tabakalı örnekleme', 'Pilot uygulama'], 'Uygun olmayan sonuçları gizlemek araştırma dürüstlüğünü bozar ve okuyucuyu yanıltır.'),
  ('Bir araştırmada toplanan kişisel veriler araştırma bittikten sonra katılımcılara söylenmeden bir reklam şirketine satılıyor. Bu davranışın ihlal ettiği temel ilke nedir?', 'Verinin yalnızca onay verilen amaçla kullanılması', ['Örneklemin rastgele seçilmesi', 'Soruların kapalı uçlu olması', 'Pilot çalışmanın yapılması'], 'Katılımcılar verilerinin yalnızca kendilerine anlatılan amaçla kullanılacağına onay vermiştir; başka amaçla paylaşmak onamı ve gizliliği çiğner.'),
  ('Bir öğretmen \'matematik yeteneğini\' ölçmek için hazırladığı testte çok uzun ve karmaşık sözel metinler kullanıyor. Bu testin hangi özelliği sorgulanmalıdır?', 'Geçerliği', ['Güvenirliği', 'Örneklem büyüklüğü', 'Yanıt oranı'], 'Test matematik yerine okuduğunu anlama becerisini de ölçüyor olabilir; bu, amaçlanan özelliğin ölçülmesini zayıflatır.'),
  ('Bir ölçeğin iki hafta arayla aynı gruba uygulanıp sonuçların karşılaştırılmasına ne ad verilir?', 'Test-tekrar test yöntemi', ['Kota yöntemi', 'Kartopu yöntemi', 'Kodlama yöntemi'], 'Test-tekrar test yöntemi, ölçeğin zaman içindeki tutarlılığını yani güvenirliğini sınar.'),
  ('Bir araştırmacı \'öğrenci mutluluğunu\' yalnızca \'Okula kaç gün devamsızlık yaptın?\' sorusuyla ölçüyor. Bu ölçümün en büyük sorunu nedir?', 'Devamsızlık mutluluğu doğrudan yansıtmaz.', ['Devamsızlık sayısı nitel bir değişkendir.', 'Soru açık uçlu olduğu için kodlanamaz.', 'Soru çift namlulu bir sorudur.'], 'Devamsızlık hastalık, ulaşım gibi pek çok başka nedene bağlıdır; mutluluğu temsil etmesi için güçlü bir dayanak yoktur.'),
  ('İki farklı gözlemcinin aynı sınıf ortamını izleyip öğrenci davranışlarını kodlaması ve kodların karşılaştırılması hangi kavramla ilgilidir?', 'Gözlemciler arası güvenirlik', ['Yanıtsızlık yanlılığı', 'Örnekleme çerçevesi', 'Kota örneklemesi'], 'Farklı gözlemcilerin aynı olayı benzer biçimde kodlaması ölçümün tutarlı olduğunu gösterir.'),
  ('Bir spor kulübü üyelerinin lisans numarasını, kemer rengini ve kilosunu kaydediyor. Bu üç değişkenden kaç tanesi nicel veridir?', '1', ['2', '3', '0'], 'Lisans numarası bir etikettir, kemer rengi sıralı bir kategoridir; yalnızca kilo nicel veridir.'),
  ('Bir öğretmen öğrencilerin sınav sonucunu \'geçti/kaldı\' olarak kaydetmek yerine puan olarak kaydetmeyi tercih ediyor. Bu tercihin avantajı nedir?', 'Daha fazla bilgi korunur.', ['Veriler nitel olduğu için daha kolay özetlenir.', 'Öğrenci sayısı otomatik olarak artar.', 'Geçme notu sınırı ortadan kalkar.'], 'Puanlar geçti/kaldı bilgisini de içerir; ayrıca öğrenciler arasındaki farkları gösterir. Tersine dönüşüm ise mümkün değildir.'),
  ('Bir otelin yıldız sayısı (1–5 yıldız) hangi ölçek düzeyine en uygun örnektir?', 'Sıralama ölçeği', ['Oran ölçeği', 'Sınıflama ölçeği', 'Aralık ölçeği'], 'Yıldızlar kalite sırası belirtir ama 4 yıldızlı otel 2 yıldızlının \'iki katı iyi\' değildir; aralıklar eşit kabul edilemez.'),
  ('Bir gıda denetçisi bir partideki 5000 kavanoz reçelden 50\'sini açıp şeker oranını ölçüyor. Bu çalışmada \'birim\' (gözlem birimi) nedir?', 'Tek bir kavanoz reçel', ['5000 kavanozun tamamı', 'Şeker oranı', '50 kavanozluk grup'], 'Ölçümün yapıldığı her bir öğe gözlem birimidir; burada her kavanoz bir birimdir.'),
  ('Bir hastane memnuniyet araştırmasında hastalar servislerine (dahiliye, cerrahi, çocuk, kadın doğum) göre ayrılıyor ve her servisin hasta listesinden rastgele hastalar seçiliyor. Servisler bu tasarımda hangi rolü oynar?', 'Tabaka', ['Küme', 'Örnekleme aralığı', 'Kota'], 'Bütün servislerden rastgele seçim yapıldığı için servisler tabaka işlevi görür.'),
  ('Bir orman mühendisi, ormanı 200 eşit kareye bölüp rastgele 10 kareyi seçiyor ve bu karelerdeki bütün ağaçları sayıyor. Kareler bu tasarımda ne işlev görür?', 'Küme', ['Tabaka', 'Kota', 'Gönüllü grup'], 'Kareler rastgele seçilen ve içindekilerin tamamı incelenen gruplardır; yani kümedir.'),
  ('Bir gazeteci, bir semtteki kira artışları hakkında haber yazmak için yalnızca kendi apartmanındaki komşularıyla konuşuyor. Bu yaklaşımın sorunu en iyi hangi ifadeyle açıklanır?', 'Tek bir apartman semtin tamamını temsil etmez.', ['Komşularla konuşmak yasal olarak yasaktır.', 'Kira artışı nicel veri olmadığından ölçülemez.', 'Bu yöntem tabakalı örnekleme sayılır.'], 'Kolayda seçilen komşular aynı bina koşullarını paylaşır; semtteki farklı konut türleri ve kira düzeyleri temsil edilmez.'),
  ('Kartopu örneklemesi olasılıklı bir örnekleme yöntemi midir?', 'Hayır, seçilme olasılıkları bilinmez.', ['Evet, her birim eşit olasılıkla seçilir.', 'Evet, çünkü ilk katılımcı rastgele seçilir.', 'Hayır, çünkü yalnızca tam sayımlarda uygulanır.'], 'Yeni katılımcılar önerilerle bulunduğundan kimin seçileceği sosyal bağlara bağlıdır; olasılıklar hesaplanamaz.'),
  ('Bir üniversite mezunlarının kazancını yalnızca mezunlar derneğine kayıtlı olanlara sorarak araştırıyor. Derneğe kayıtlı olanlar daha çok kariyerinde başarılı mezunlarsa tahmin nasıl etkilenir?', 'Kazanç olduğundan yüksek tahmin edilir.', ['Kazanç olduğundan düşük tahmin edilir.', 'Tahmin hiç etkilenmez.', 'Tahminin yönü belirlenemez.'], 'Çerçeve başarılı mezunları fazla içerdiğinden kazanç tahmini yukarı doğru yanlı olur.'),
  ('İki anketten A\'nın yanıt oranı %85, B\'nin yanıt oranı %20\'dir; ikisi de rastgele seçilmiş örneklemlere uygulanmıştır. Yanıtsızlık yanlılığı riski açısından hangisi doğrudur?', 'Risk B\'de daha yüksektir.', ['Risk A\'da daha yüksektir.', 'İkisinde risk eşittir.', 'Yanıt oranı yanlılık riskini etkilemez.'], 'Yanıt oranı düştükçe yanıt verenlerin örneklemi temsil etmeme olasılığı artar; düşük yanıt oranı tek başına yanlılık kanıtı değildir ama riski büyütür.'),
  ('Bir ankette katılımcılara günde kaç bardak su içtikleri soruluyor; birçok kişi \'8 bardak\' yanıtını veriyor. Bu yanıtların yaygınlığının olası bir açıklaması nedir?', 'Önerilen miktarın bildirilmesi', ['Herkesin gerçekten tam 8 bardak su içmesi', 'Sorunun çift namlulu olması', 'Örnekleme çerçevesinin eksik olması'], 'Yaygın olarak önerilen bir değer, kişilerin gerçek tüketim yerine \'olması gereken\' yanıtı vermesine yol açabilir.'),
  ('Bir katılımcının yanıtları, ankette bir önceki soruda kendi verdiği yanıtla tutarlı görünme isteğiyle değişiyorsa bu hangi tür hataya örnektir?', 'Yanıt yanlılığı', ['Kapsam hatası', 'Örnekleme değişkenliği', 'Kota hatası'], 'Ölçüm sırasında kişinin gerçek durumu yerine başka kaygılarla yanıt vermesi yanıt yanlılığıdır.'),
  ('Bir anket hazırlayıcısı \'Pek çok veli okul kıyafetinin pahalı olduğunu düşünüyor. Siz de okul kıyafetinin pahalı olduğunu düşünüyor musunuz?\' sorusunu yazıyor. Bu sorunun ilk cümlesi nasıl bir etki yaratır?', 'Uyum baskısıyla yanıtı yönlendirir.', ['Soruyu daha tarafsız hâle getirir.', 'Yanıt oranını kesinlikle azaltır.', 'Soruyu açık uçlu hâle getirir.'], 'Çoğunluğun görüşünü önceden bildirmek, katılımcıyı bu görüşe katılmaya yöneltir.'),
  ('Bir okul, öğrencilerin kahvaltı yapıp yapmamasını (anket) ve sınav başarısını karşılaştırıyor. Kahvaltı yapanların daha başarılı olduğu görülüyor. Kahvaltının başarıyı artırdığını göstermek için en güçlü tasarım hangisi olurdu?', 'Öğrencileri rastgele iki gruba ayırıp birine kahvaltı vermek', ['Daha fazla öğrenciye aynı anketi uygulamak', 'Yalnızca başarılı öğrencilere kahvaltıyı sormak', 'Ailelerin görüşünü almak'], 'Rastgele atamalı deney, aile geliri ya da uyku düzeni gibi karıştırıcı etkenleri gruplar arasında dengeler.'),
  ('Bir sütun grafiği bir hayvan barınağındaki hayvanları gösteriyor: kedi 36, köpek 24, tavşan 8, kuş 12. Kedilerin bütün hayvanlar içindeki payı yüzde kaçtır?', '%45', ['%36', '%30', '%55,5'], 'Toplam hayvan 36 + 24 + 8 + 12 = 80\'dir; 36 / 80 = %45.'),
  ('Bir sütun grafiği bir okulun kantininde pazartesiden cumaya satılan ayran sayılarını 60, 45, 70, 45, 80 olarak gösteriyor. Hangi iki günde satış birbirine eşittir?', 'Salı ve perşembe', ['Pazartesi ve çarşamba', 'Çarşamba ve cuma', 'Pazartesi ve cuma'], 'Salı ve perşembe günlerinin ikisinde de 45 ayran satılmıştır.'),
  ('Bir sütun grafiğinde dört ilçenin yıllık yağış miktarı (mm) şöyle: Kuzey 820, Güney 410, Doğu 615, Batı 1025. Kuzey ilçesinin yağışı ile Güney ilçesinin yağışı arasındaki ilişki nedir?', 'Kuzey\'in yağışı Güney\'inkinin iki katıdır.', ['Güney\'in yağışı Kuzey\'inkinin iki katıdır.', 'İki ilçenin yağışı birbirine eşittir.', 'Kuzey\'in yağışı Batı\'nınkinden fazladır.'], '820 / 410 = 2\'dir; Kuzey\'in yağışı Güney\'inkinin iki katıdır.'),
  ('Bir çizgi grafiği bir bebeğin ilk altı aydaki kilosunu gösteriyor (kg): doğum 3,2; 1. ay 4,1; 2. ay 5,0; 3. ay 5,8; 4. ay 6,4; 5. ay 6,9; 6. ay 7,3. Aylık kilo artışı için hangisi doğrudur?', 'Artış ilk aylarda büyüktür, sonra yavaşlar.', ['Artış her ay tam olarak aynı miktardadır.', 'Bebek 3. aydan sonra kilo kaybetmiştir.', 'Artış ilk aylarda küçüktür, sonra hızlanır.'], 'Aylık artışlar 0,9; 0,9; 0,8; 0,6; 0,5; 0,4 kg\'dır; artış giderek küçülmektedir.'),
  ('Bir sınıftaki öğrencilerin en sevdiği mevsim daire grafiğiyle gösteriliyor: yaz 162°, ilkbahar 90°, kış 72°, sonbahar 36°. Sınıfta 40 öğrenci varsa yazı seçen kaç öğrenci vardır?', '18', ['16', '20', '16,2'], '162 / 360 · 40 = 18 öğrenci.'),
  ('Bir daire grafiğinde iki dilimin açıları 2:3 oranındadır ve toplamları 180°\'dir. Büyük dilimin açısı kaç derecedir?', '108°', ['72°', '120°', '90°'], '180 derece 2 + 3 = 5 paya bölünür; her pay 36°\'dir. Büyük dilim 3 · 36 = 108°.'),
  ('Bir spor salonunda 120 üyeden 50\'si sabah, 70\'i akşam geliyor. Sabah gelenlerden 30\'u, akşam gelenlerden 28\'i kadındır. Akşam gelenler arasında erkeklerin oranı yüzde kaçtır?', '%60', ['%40', '%35', '%46,7'], 'Akşam gelenlerden 70 − 28 = 42\'si erkektir; 42 / 70 = %60.'),
  ('Bir fabrikada 50 işçinin günlük üretim adetleri gruplanmış: 10–14: 6, 15–19: 14, 20–24: 18, 25–29: 9, 30–34: 3. Günde en az 20 ürün üreten işçilerin oranı yüzde kaçtır?', '%60', ['%36', '%40', '%18'], '20 ve üzeri üretenler 18 + 9 + 3 = 30 işçidir; 30 / 50 = %60.'),
  ('Bir sınavda \'puanı x\'ten az olan öğrenci yüzdesi\' şöyle veriliyor: 50\'den az %10, 60\'tan az %25, 70\'ten az %55, 80\'den az %85, 90\'dan az %95. Öğrencilerin yüzde kaçı 60 ile 79 arasında puan almıştır?', '%60', ['%30', '%85', '%35'], '80\'den az olanlar %85, 60\'tan az olanlar %25\'tir; fark %60\'tır.'),
  ('Bir dağılımın birikimli frekansları 3, 10, 22, 30\'dur. Gözlemlerin yarısından fazlası hangi kategoriye kadar birikmiş olur?', 'Üçüncü kategoriye', ['İkinci kategoriye', 'Birinci kategoriye', 'Dördüncü kategoriye'], 'Toplam 30\'dur, yarısı 15\'tir. İkinci kategoride 10, üçüncüde 22 birikir; 15 ilk kez üçüncü kategoride aşılır.'),
  ('Bir gövde-yaprak gösterimi bir otobüs hattındaki yolculuk sürelerini (dakika) veriyor: 1 | 8 9, 2 | 1 3 3 6 7, 3 | 0 2 4, 4 | 5. Kaç yolculuk yarım saatten uzun sürmüştür?', '3', ['4', '2', '5'], '30\'dan büyük değerler 32, 34 ve 45\'tir; 30 tam yarım saattir. Toplam 3 yolculuk.'),
  ('Bir kutu grafiğinde en küçük değer 4, birinci çeyrek 10, ortanca 14, üçüncü çeyrek 20, en büyük değer 35 olarak işaretlenmiştir. Verilerin yaklaşık yüzde kaçı 10 ile 35 arasındadır?', '%75', ['%50', '%25', '%100'], 'Birinci çeyreğin üstünde verilerin yaklaşık %75\'i bulunur ve bunlar en büyük değere kadar uzanır.'),
  ('Bir kutu grafiğinde verilen beş sayılık özet 4, 10, 14, 20, 35\'tir. Verilerin yaklaşık dörtte biri hangi aralıkta yer alır?', '20 ile 35 arasında', ['4 ile 20 arasında', '10 ile 20 arasında', '4 ile 14 arasında'], 'Üçüncü çeyrek ile en büyük değer arasında verilerin yaklaşık son %25\'i bulunur.'),
  ('Bir köydeki hanelerin sahip olduğu inek sayısını (0, 1, 2, 3, 4, 5) göstermek isteyen bir öğrenci için en uygun ve basit gösterim hangisidir?', 'Nokta grafiği', ['Çizgi grafiği', 'Daire grafiği', 'Çift eksenli grafik'], 'Az sayıda kesikli değer için her haneyi bir noktayla gösteren nokta grafiği hem basit hem okunaklıdır.'),
  ('Bir ülkenin nüfus sayımı on yılda bir yapılıyor. Aradaki yıllarda nüfusla ilgili güncel bilgi elde etmek için en çok neye başvurulur?', 'Örneklem anketlerine ve kayıt sistemlerine', ['Her yıl yeni bir tam sayıma', 'Yalnızca bir önceki sayımın aynısına', 'Gönüllü internet oylamalarına'], 'Tam sayımlar pahalı ve seyrektir; ara dönemlerde rastgele örneklemli hane anketleri ve idari kayıtlar kullanılır.'),
  ('Bir araştırmacı bir ildeki evsizlerin yaşam koşullarını incelemek istiyor. Bu araştırmada standart bir örnekleme çerçevesi bulmanın zor olmasının nedeni nedir?', 'Evsizlerin kayıtlı adresi ve güncel listesi yoktur.', ['Evsizlerin sayısı her zaman sıfırdır.', 'Evsizler hiçbir zaman araştırmaya katılmaz.', 'Bu konuda yalnızca deney yapılabilir.'], 'Hane listeleri ya da adres kayıtları evsizleri kapsamaz; bu tür gruplar için barınak kayıtları, alan taraması ya da kartopu yöntemleri kullanılır.'),
  ('Bir televizyon kanalı, izleyicilerden ücretli SMS ile oy vermelerini istiyor. Bu yöntemin gönüllü yanıt sorununa ek olarak getirdiği bir yanlılık kaynağı nedir?', 'Aynı kişinin birden çok oy verebilmesi', ['Oyların sayılamaması', 'SMS\'in kesikli veri olması', 'Kanalın tam sayım yapması'], 'Kişi sınırlaması olmadığında çok istekli izleyiciler defalarca oy vererek sonucu kendi lehlerine çevirebilir.'),
  ('Bir sağlık anketinde katılımcılar kilolarını bildirirken gerçekte ölçülen kilolarından ortalama birkaç kilo az değer söylüyor. Bu sapmanın doğru adı nedir?', 'Kendi bildirimine dayalı ölçüm yanlılığı', ['Örnekleme hatası', 'Kapsam hatası', 'Kota hatası'], 'Kişilerin kendi beyanları gerçek ölçümlerden sistematik olarak saparsa bu bir ölçüm (yanıt) yanlılığıdır; tartı ile ölçüm bu sorunu azaltır.'),
  ('Bir ankette katılımcılar \'Okul yemeklerinden memnunum.\' ifadesine beşli ölçekle yanıt veriyor: 12 kişi \'Kesinlikle katılmıyorum\', 18 \'Katılmıyorum\', 25 \'Kararsızım\', 30 \'Katılıyorum\', 15 \'Kesinlikle katılıyorum\'. Olumlu görüş bildirenlerin oranı yüzde kaçtır?', '%45', ['%30', '%55', '%15'], 'Olumlu yanıtlar 30 + 15 = 45 kişidir; toplam 100 kişidir; oran %45.'),
  ('Bir akupunktur çalışmasında kontrol grubuna iğneler cilde batmayan, geri çekilen özel iğnelerle \'sahte\' uygulama yapılıyor. Bu uygulamanın amacı nedir?', 'Plasebo işlevi görerek beklenti etkisini ayırmak', ['Kontrol grubunu tedaviden tamamen ayırmak', 'Gerçek uygulamanın etkisini artırmak', 'Katılımcı sayısını azaltmak'], 'Sahte uygulama katılımcının tedavi aldığını düşünmesini sağlar; böylece gerçek iğnelerin ek etkisi ölçülebilir.'),
  ('Bir öğrenci anket verilerini girerken \'Doğum tarihi\' sütununa bazı satırlarda gün/ay/yıl, bazılarında ay/gün/yıl biçimi kullanıyor. Bu tutarsızlık hangi soruna yol açabilir?', 'Bazı tarihler yanlış okunur.', ['Veri seti kendiliğinden küçülür.', 'Tarihler nitel olmaktan çıkar.', 'Kayıp veriler ortaya çıkmaz.'], 'Örneğin 03/04 hem 3 Nisan hem 4 Mart olarak okunabilir; verilerin tek biçimde girilmesi gerekir.'),
  ('Bir öğretmen sınıfındaki öğrencilere notları etkilenecekmiş gibi göstererek ankete katılmalarını şart koşuyor. Bu durum hangi etik ilkeyi zedeler?', 'Katılımın gönüllülüğü', ['Örneklemin büyüklüğü', 'Verilerin kodlanması', 'Soruların sıralaması'], 'Katılım baskıyla elde edilirse gönüllülük ilkesi çiğnenir; bu yanıtların dürüstlüğünü de olumsuz etkileyebilir.'),
  ('Bir öğrencinin aynı gün içinde aynı kronometreyle 100 metre koşusu üç kez ölçülüyor ve sonuçlar 14,1; 14,0; 14,2 saniye çıkıyor. Bu ölçümler en çok neyi gösterir?', 'Ölçümlerin tutarlı olduğunu', ['Kronometrenin bozuk olduğunu', 'Öğrencinin her seferinde yavaşladığını', 'Ölçümlerin geçersiz olduğunu'], 'Değerler birbirine çok yakındır; bu, ölçümün güvenirliğinin (tutarlılığının) yüksek olduğunu gösterir.'),
  ('Bir trafik gözlemcisi 15 dakikada geçen araçları çeteleyle kaydediyor: otomobil için 7 tam beşli grup ve 3 çizgi, kamyon için 2 tam beşli grup, motosiklet için 4 çizgi. Toplam kaç araç geçmiştir?', '52', ['48', '14', '42,5'], 'Otomobil 38, kamyon 10, motosiklet 4: 38 + 10 + 4 = 52.'),
  ('Bir otobüs firmasının 2020 yılında yaptığı 800 seferden 56\'sı gecikmeli. Gecikmeli seferlerin oranı binde kaçtır?', '70', ['56', '7', '700'], '56 / 800 = 0,07; binde 70\'tir.'),
  ('Bir sütun grafiği bir çiftçinin dört ürününden aldığı verimi (ton) gösteriyor: buğday 12, arpa 8, mısır 15, yulaf 5. Mısır ve yulafın toplam verimi buğday ve arpanınkiyle karşılaştırılırsa hangisi doğrudur?', 'İki toplam birbirine eşittir.', ['Mısır ve yulaf 5 ton fazladır.', 'Buğday ve arpa 5 ton fazladır.', 'Mısır ve yulaf iki katıdır.'], 'Mısır + yulaf = 20 ton, buğday + arpa = 20 ton; toplamlar eşittir.'),
  ('Bir çizgi grafiği bir barajın doluluk oranını aylara göre gösteriyor: ocak %62, şubat %70, mart %78, nisan %83, mayıs %80, haziran %71. Doluluğun bir önceki aya göre en çok azaldığı ay, yılın kaçıncı ayıdır?', 'Altıncı ay', ['Beşinci ay', 'Dördüncü ay', 'İkinci ay'], 'Mayısta 3 puan, haziranda 9 puan azalma vardır; en büyük düşüş haziranda olmuştur.'),
  ('Bir çizgi grafiğinde iki kentin aylık işsizlik oranı veriliyor. A kentinin çizgisi dalgalı ama yatay, B kentinin çizgisi düzenli biçimde aşağı iniyor. Bu bilgilerden en doğru çıkarım hangisidir?', 'B\'de işsizlik azalma eğilimindedir.', ['A\'da işsizlik her ay artmaktadır.', 'B\'nin işsizliği A\'nınkinden kesinlikle yüksektir.', 'A\'da işsizlik sıfırdır.'], 'Aşağı yönlü çizgi azalma eğilimini gösterir; iki kentin düzeyi hakkında ek bilgi olmadan karşılaştırma yapılamaz.'),
  ('Bir daire grafiğinde \'kitap\' dilimi 54°, \'film\' dilimi 126° olarak çizilmiştir. Film diliminin kitap dilimine oranı kaçtır?', '7/3', ['3/7', '2', '72'], '126 / 54 = 7/3 ≈ 2,33\'tür.'),
  ('Bir histogramda bir okulun 120 öğrencisinin okula ulaşım süresi gösteriliyor: 0–10 dk: 30, 10–20 dk: 45, 20–30 dk: 25, 30–40 dk: 15, 40–50 dk: 5. Ulaşım süresi 20 dakika ve üzeri olan öğrencilerin oranı yüzde kaçtır?', 'Yaklaşık %37,5', ['%25', '%62,5', 'Yaklaşık %20,8'], '20 dakika ve üzeri 25 + 15 + 5 = 45 öğrencidir; 45 / 120 = %37,5.'),
  ('Bir histogramın sütunları soldan sağa düzenli olarak yükseliyor ve en yüksek sütun en sağda. Bu dağılım biçimi nasıl tanımlanır?', 'Sola çarpık', ['Sağa çarpık', 'Tekdüze', 'Simetrik'], 'Gözlemler büyük değerlerde yoğunlaşıp kuyruk sola uzanıyorsa dağılım sola (negatif) çarpıktır.'),
  ('Bir kutu grafiğinde bir şehrin günlük sıcaklık değerlerinin beş sayılık özeti 8, 15, 19, 23, 31 °C\'dir. Günlerin yaklaşık yüzde kaçında sıcaklık 15 °C\'nin altındadır?', '%25', ['%50', '%15', '%75'], 'Birinci çeyrek 15 °C\'dir; değerlerin yaklaşık %25\'i bunun altındadır.'),
  ('Bir ankette 160 kişiye evcil hayvan sahipliği ve yaşadıkları yer soruluyor: kentte yaşayan ve hayvanı olan 40, kentte yaşayan ve hayvanı olmayan 60, kırsalda yaşayan ve hayvanı olan 42, kırsalda yaşayan ve hayvanı olmayan 18. Kırsalda yaşayanların yüzde kaçının evcil hayvanı vardır?', '%70', ['%42', '%51,2', '%26,3'], 'Kırsalda 42 + 18 = 60 kişi yaşar; 42 / 60 = %70.'),
  ('Bir nokta grafiğinde 1\'den 6\'ya kadar değerlerin üzerinde sırasıyla 0, 2, 5, 5, 2, 0 nokta var. Bu grafikle ilgili hangisi doğrudur?', 'Toplam 14 gözlem vardır ve dağılım simetriktir.', ['Toplam 6 gözlem vardır.', 'Dağılım sağa çarpıktır.', 'En sık değer yalnızca 1\'dir.'], '0 + 2 + 5 + 5 + 2 + 0 = 14 gözlem vardır; frekanslar 3,5 çevresinde iki yana eşit dağılmıştır.'),
  ('Bir okul yeni bir okuma programını yalnızca bir sınıfta uyguluyor ve yıl sonunda bu sınıfın okuma puanının arttığını görüyor. Kontrol grubu olmamasının yarattığı sorun nedir?', 'Artış başka etkenlerden de kaynaklanabilir.', ['Okuma puanı ölçülemez.', 'Program kesinlikle etkisizdir.', 'Artış yalnızca şans eseri olamaz.'], 'Öğrenciler bir yıl içinde doğal olarak da gelişir; karşılaştırma grubu olmadan programın ek etkisi ayrılamaz.'),
  ('Bir vitamin çalışmasında plasebo hapları gerçek haplardan farklı renkte üretiliyor. Bu durum çalışmayı nasıl etkileyebilir?', 'Katılımcılar grubunu anlayıp körleme bozulur.', ['Plasebo etkisi tamamen artar ve sonuç kesinleşir.', 'Örneklem büyüklüğü azalır.', 'Hapların etkisi değişmez, sorun yoktur.'], 'Körlemenin işe yaraması için plasebo görünüm, tat ve kullanım bakımından gerçek uygulamaya benzer olmalıdır.'),
  ('Bir araştırmacı bir sınıftaki öğrencilerin hem boyunu hem de kilosunu tek tek, birlikte göstermek istiyor. Aşağıdakilerden hangisi bu amaca uygun değildir?', 'Daire grafiği', ['Her öğrencinin bir nokta olduğu iki eksenli nokta çizimi', 'İki sütunlu ham veri listesi', 'Boy ve kilonun yan yana yazıldığı kayıt çizelgesi'], 'Daire grafiği bir bütünün parçalarını gösterir; iki sayısal değişkeni birlikte göstermek için uygun değildir.'),
  ('Bir sınıfta 30 öğrencinin 18\'i futbol, 14\'ü basketbol oynuyor ve 6 öğrenci ikisini de oynuyor. İki spordan hiçbirini oynamayan öğrenci sayısı kaçtır?', '4', ['2', '10', '12'], 'En az birini oynayanlar 18 + 14 − 6 = 26\'dır; 30 − 26 = 4 öğrenci ikisini de oynamaz.'),
  ('Bir piktogramda her balık simgesi 15 balığı gösteriyor. Bir göletin sayımında 5 tam simge ve 2/3 simge çizilmiş. Gölette kaç balık sayılmıştır?', '85', ['75', '80', '52/3'], '5 · 15 + (2/3) · 15 = 75 + 10 = 85.'),
  ('Bir mobil uygulama, kullanıcıları arasında yaptığı ankette \'Türkiye\'de insanların %70\'i akıllı telefonla alışveriş yapıyor.\' sonucunu duyuruyor. Bu genellemedeki temel sorun nedir?', 'Uygulama kullanıcıları dışında kalanlar seçilemez.', ['Ankette yüzde hesabı yapılmamıştır.', 'Akıllı telefon kullanımı ölçülemez.', 'Ankete çok fazla kişi katılmıştır.'], 'Örneklem yalnızca uygulamayı kullananlardan oluştuğu için akıllı telefonla alışverişe yatkın kişileri fazla temsil eder.'),
  ('Bir araştırmacı hem \'Okulda kendinizi güvende hissediyor musunuz? (Evet/Hayır)\' hem de \'Neden?\' sorularını birlikte kullanıyor. Bu birleşimin yararı nedir?', 'Sayılabilir yanıtla birlikte gerekçeyi de toplamak', ['Anketi tamamen kapalı uçlu yapmak', 'Yanıt seçeneklerini azaltıp kodlamayı engellemek', 'Katılımcıların gerekçe yazmasını önlemek'], 'Kapalı uçlu kısım kolay özetlenir; açık uçlu takip sorusu yanıtların nedenlerini anlamayı sağlar.'),
  ('Bir araştırmacı çocukların kelime dağarcığının yaşla nasıl geliştiğini öğrenmek istiyor ve sonucu bir ay içinde raporlaması gerekiyor. Hangi tasarımı seçmesi daha gerçekçidir?', 'Farklı yaşlardan çocuklarla kesitsel çalışma', ['Aynı çocukları 10 yıl izleyen boylamsal çalışma', 'Tek bir çocukla yapılan tam sayım', 'Plasebo kontrollü deney'], 'Kısa sürede sonuç gerektiğinde farklı yaş gruplarının aynı anda incelendiği kesitsel tasarım uygulanabilir tek seçenektir.'),
  ('Bir çizgi grafiği bir kentin 2010–2015 nüfusunu (bin) gösteriyor: 200, 210, 225, 245, 270, 300. Yıllık artışlar için hangisi doğrudur?', 'Artış miktarı her yıl büyümektedir.', ['Artış miktarı her yıl aynıdır.', 'Nüfus 2013\'ten sonra azalmıştır.', 'Artış miktarı her yıl küçülmektedir.'], 'Yıllık artışlar 10, 15, 20, 25, 30 bindir; her yıl artış miktarı büyümektedir.'),
  ('Bir daire grafiği bir ilçedeki 900 hanenin ısınma biçimini gösteriyor: doğalgaz 240°, kömür 80°, elektrik 40°. Kömürle ısınan hane sayısı kaçtır?', '200', ['80', '100', '600'], '80 / 360 · 900 = 200 hane.'),
  ('Bir öğretmen yazılı sınav kâğıtlarını iki farklı günde yeniden puanladığında aynı kâğıtlara çok farklı notlar veriyor. Bu durumun çözümü için en uygun önlem hangisidir?', 'Ayrıntılı bir puanlama anahtarı kullanmak', ['Soruları daha zor hâle getirmek', 'Sınav süresini uzatmak', 'Öğrenci sayısını azaltmak'], 'Açık ölçütler içeren puanlama anahtarı, puanlayanın kişisel yargısını sınırlayarak tutarlılığı artırır.'),
];
